	{ name = "Cookiemancy", desc = "Wizard towers are twice as efficient.", quote = "There it is; the perfected school of baking magic. From summoning chips to hexing nuts, there is not a single part of cookie-making that hasn't been improved tenfold by magic tricks.", price = 1.65e20, icon = {17,16}, tier = 7, building = "Wizard tower", b1 = "Wizard tower", order = 5.753e2 },
	{ name = "Dyson sphere", desc = "Shipments are twice as efficient.", quote = "You've found a way to apply your knowledge of cosmic technology to slightly more local endeavors; this gigantic sphere of meta-materials, wrapping the solar system, is sure to kick your baking abilities up a notch.", price = 2.55e21, icon = {5,16}, tier = 7, building = "Shipment", b1 = "Shipment", order = 6.00301e2 },
	{ name = "Theory of atomic fluidity", desc = "Alchemy labs are twice as efficient.", quote = "Pushing alchemy to its most extreme limits, you find that everything is transmutable into anything else - lead to gold, mercury to water; more importantly, you realize that anything can -and should- be converted to cookies.", price = 3.75e22, icon = {6,16}, tier = 7, building = "Alchemy lab", b1 = "Alchemy lab", order = 7.00302e2 },
	{ name = "End of times back-up plan", desc = "Portals are twice as efficient.", quote = "Just in case, alright?", price = 5e23, icon = {7,16}, tier = 7, building = "Portal", b1 = "Portal", order = 8.00303e2 },
	{ name = "Great loop hypothesis", desc = "Time machines are twice as efficient.", quote = "What if our universe is just one instance of an infinite cycle? What if, before and after it, stretched infinite amounts of the same universe, themselves containing infinite amounts of cookies?", price = 7e24, icon = {8,16}, tier = 7, building = "Time machine", b1 = "Time machine", order = 9.00304e2 },
	{ name = "The Pulse", desc = "Antimatter condensers are twice as efficient.", quote = "You've tapped into the very pulse of the cosmos, a timeless rhythm along which every material and antimaterial thing beats in unison. This, somehow, means more cookies.", price = 8.5e25, icon = {13,16}, tier = 7, building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.000305e3 },
	{ name = "Lux sanctorum", desc = "Prisms are twice as efficient.", quote = "Your prism attendants have become increasingly mesmerized with something in the light - or maybe something beyond it; beyond us all, perhaps?", price = 1.05e27, icon = {14,16}, tier = 7, building = "Prism", b1 = "Prism", order = 1.100306e3 },
	{ name = "The Unbridling", desc = "Grandmas are twice as efficient.", quote = "It might be a classic tale of bad parenting, but let's see where grandma is going with this.", price = 5e16, icon = {1,17}, tier = 8, building = "Grandma", b1 = "Grandma", order = 2.00307e2 },
	{ name = "Wheat triffids", desc = "Farms are twice as efficient.", quote = "Taking care of crops is so much easier when your plants can just walk about and help around the farm.Do not pet. Do not feed. Do not attempt to converse with.", price = 5.5e17, icon = {2,17}, tier = 8, building = "Farm", b1 = "Farm", order = 3.00308e2 },
	{ name = "Canola oil wells", desc = "Mines are twice as efficient.", quote = "A previously untapped resource, canola oil permeates the underground olifers which grant it its particular taste and lucrative properties.", price = 6e18, icon = {3,17}, tier = 8, building = "Mine", b1 = "Mine", order = 4.00309e2 },
	{ name = "78-hour days", desc = "Factories are twice as efficient.", quote = "Why didn't we think of this earlier?", price = 6.5e19, icon = {4,17}, tier = 8, building = "Factory", b1 = "Factory", order = 5.0031e2 },
	{ name = "The stuff rationale", desc = "Banks are twice as efficient.", quote = "If not now, when? If not it, what? If not things... stuff?", price = 7e20, icon = {15,17}, tier = 8, building = "Bank", b1 = "Bank", order = 5.25311e2 },
	{ name = "Theocracy", desc = "Temples are twice as efficient.", quote = "You've turned your cookie empire into a perfect theocracy, gathering the adoration of zillions of followers from every corner of the universe.Don't let it go to your head.", price = 1e22, icon = {16,17}, tier = 8, building = "Temple", b1 = "Temple", order = 5.50312e2 },
	{ name = "Rabbit trick", desc = "Wizard towers are twice as efficient.", quote = "Using nothing more than a fancy top hat, your wizards have found a way to simultaneously curb rabbit population and produce heaps of extra cookies for basically free!Resulting cookies may or may not be fit for vegans.", price = 1.65e23, icon = {17,17}, tier = 8, building = "Wizard tower", b1 = "Wizard tower", order = 5.75313e2 },
	{ name = "The final frontier", desc = "Shipments are twice as efficient.", quote = "It's been a long road, getting from there to here. It's all worth it though - the sights are lovely and the oil prices slightly more reasonable.", price = 2.55e24, icon = {5,17}, tier = 8, building = "Shipment", b1 = "Shipment", order = 6.00314e2 },
