	{ name = "Butterscotch cookies", desc = "Cookie production multiplier +4%.", quote = "The butterscotch chips are just the right amount of sticky, and make you feel like you're eating candy.", price = 5e34, icon = {24,20}, pool = "cookie", power = 4, unlockCookies = 2.5e33, order = 1.0020468e4 },
	{ name = "Speculaas", desc = "Cookie production multiplier +4%.", quote = "These crunchy, almost obnoxiously cinnamony cookies are a source of dutch pride. About the origin of the name, one can only speculate.", price = 1e35, icon = {21,20}, pool = "cookie", power = 4, unlockCookies = 5e33, order = 1.0020469e4 },
	{ name = "Elderwort biscuits", desc = "Cookie production multiplier +2%.Grandmas are 2% more powerful.Dropped by elderwort plants.Cost scales with CpS.", quote = "They taste incredibly stale, even when baked fresh.", price = 0, icon = {22,25}, pool = "cookie", power = 2, lasting = true, order = 1.020047e4 },
	{ name = "Bakeberry cookies", desc = "Cookie production multiplier +2%.Dropped by bakeberry plants.Cost scales with CpS.", quote = "Really good dipped in hot chocolate.", price = 0, icon = {23,25}, pool = "cookie", power = 2, lasting = true, order = 1.0200471e4 },
	{ name = "Duketater cookies", desc = "Cookie production multiplier +10%.Dropped by duketater plants.Cost scales with CpS.", quote = "Fragrant and mealy, with a slight yellow aftertaste.", price = 0, icon = {24,25}, pool = "cookie", power = 10, lasting = true, order = 1.0200472e4 },
	{ name = "Green yeast digestives", desc = "Golden cookies give 1% more cookies.Golden cookie effects last 1% longer.Golden cookies appear 1% more often.Random drops are 3% more common.Dropped by green rot plants.Cost scales with CpS.", quote = "These are tastier than you'd expect, but not by much.", price = 0, icon = {25,25}, pool = "cookie", lasting = true, order = 1.0200473e4 },
	{ name = "Fern tea", desc = "You gain another +3% of your regular CpS while the game is closed. (Must own the Twin Gates of Transcendence upgrade.)Dropped by drowsyfern plants.Cost scales with CpS.", quote = "A chemically complex natural beverage, this soothing concoction has been used by mathematicians to solve equations in their sleep.", price = 0, icon = {26,25}, lasting = true, order = 2.3000474e4 },
	{ name = "Ichor syrup", desc = "You gain another +7% of your regular CpS while the game is closed. (Must own the Twin Gates of Transcendence upgrade.)Sugar lumps mature 7 minutes sooner.Dropped by ichorpuff plants.Cost scales with CpS.", quote = "Tastes like candy. The smell is another story.", price = 0, icon = {27,25}, lasting = true, order = 2.3000475e4 },
	{ name = "Wheat slims", desc = "Cookie production multiplier +1%.Dropped by baker's wheat plants.Cost scales with CpS.", quote = "The only reason you'd consider these to be cookies is because you feel slightly sorry for them.", price = 0, icon = {28,25}, pool = "cookie", power = 1, lasting = true, order = 1.0200476e4 },
	{ name = "Synthetic chocolate green honey butter biscuit", desc = "Cookie production multiplier +10%.", quote = "Rewarded for owning 350 of everything.The recipe for this butter biscuit was once the sole heritage of an ancient mountain monastery. Its flavor is so refined that only a slab of lab-made chocolate specifically engineered to be completely tasteless could complement it.Also it's got your face on it.", price = 1e44, icon = {24,26}, pool = "cookie", power = 10, order = 1.0300477e4 },
	{ name = "Royal raspberry chocolate butter biscuit", desc = "Cookie production multiplier +10%.", quote = "Rewarded for owning 400 of everything.Once reserved for the megalomaniac elite, this unique strain of fruity chocolate has a flavor and texture unlike any other. Whether its exorbitant worth is improved or lessened by the presence of your likeness on it still remains to be seen.", price = 1e47, icon = {25,26}, pool = "cookie", power = 10, order = 1.0300478e4 },
	{ name = "Ultra-concentrated high-energy chocolate butter biscuit", desc = "Cookie production multiplier +10%.", quote = "Rewarded for owning 450 of everything.Infused with the power of several hydrogen bombs through a process that left most nuclear engineers and shareholders perplexed. Currently at the center of some rather heated United Nations meetings. Going in more detail about this chocolate would violate several state secrets, but we'll just add that someone's bust seems to be pictured on it. Perhaps yours?", price = 1e50, icon = {26,26}, pool = "cookie", power = 10, order = 1.0300479e4 },
	{ name = "Timeproof hair dyes", desc = "Grandmas are twice as efficient.", quote = "Why do they always have those strange wispy pink dos? What do they know about candy floss that we don't?", price = 5e22, icon = {1,19}, tier = 10, building = "Grandma", b1 = "Grandma", order = 2.0048e2 },
	{ name = "Barnstars", desc = "Farms are twice as efficient.", quote = "Ah, yes. These help quite a bit. Somehow.", price = 5.5e23, icon = {2,19}, tier = 10, building = "Farm", b1 = "Farm", order = 3.00481e2 },
	{ name = "Mine canaries", desc = "Mines are twice as efficient.", quote = "These aren't used for anything freaky! The miners just enjoy having a pet or two down there.", price = 6e24, icon = {3,19}, tier = 10, building = "Mine", b1 = "Mine", order = 4.00482e2 },
	{ name = "Brownie point system", desc = "Factories are twice as efficient.", quote = "Oh, these are lovely! You can now reward your factory employees for good behavior, such as working overtime or snitching on coworkers. 58 brownie points gets you a little picture of a brownie, and 178 of those pictures gets you an actual brownie piece for you to do with as you please! Infantilizing? Maybe. Oodles of fun? You betcha!", price = 6.5e25, icon = {4,19}, tier = 10, building = "Factory", b1 = "Factory", order = 5.00483e2 },
	{ name = "Grand supercycles", desc = "Banks are twice as efficient.", quote = "We let the public think these are complicated financial terms when really we're just rewarding the bankers with snazzy bicycles for a job well done. It's only natural after you built those fancy gold swimming pools for them, where they can take a dip and catch Kondratiev waves.", price = 7e26, icon = {15,19}, tier = 10, building = "Bank", b1 = "Bank", order = 5.25484e2 },
	{ name = "Psalm-reading", desc = "Temples are twice as efficient.", quote = "A theologically dubious and possibly blasphemous blend of fortune-telling and scripture studies.", price = 1e28, icon = {16,19}, tier = 10, building = "Temple", b1 = "Temple", order = 5.50485e2 },
	{ name = "Immobile spellcasting", desc = "Wizard towers are twice as efficient.", quote = "Wizards who master this skill can now cast spells without having to hop and skip and gesticulate embarrassingly, which is much sneakier and honestly quite a relief.", price = 1.65e29, icon = {17,19}, tier = 10, building = "Wizard tower", b1 = "Wizard tower", order = 5.75486e2 },
	{ name = "Restaurants at the end of the universe", desc = "Shipments are twice as efficient.", quote = "Since the universe is spatially infinite, and therefore can be construed to have infinite ends, you've opened an infinite chain of restaurants where your space truckers can rest and partake in some home-brand cookie-based meals.", price = 2.55e30, icon = {5,19}, tier = 10, building = "Shipment", b1 = "Shipment", order = 6.00487e2 },
	{ name = "On second thought", desc = "Alchemy labs are twice as efficient.", quote = "Disregard that last upgrade, alchemy is where it's at! Your eggheads just found a way to transmute children's nightmares into rare metals!", price = 3.75e31, icon = {6,19}, tier = 10, building = "Alchemy lab", b1 = "Alchemy lab", order = 7.00488e2 },
	{ name = "Dimensional garbage gulper", desc = "Portals are twice as efficient.", quote = "So we've been looking for a place to dispose of all the refuse that's been accumulating since we started baking - burnt cookies, failed experiments, unruly workers - and well, we figured rather than sell it to poor countries like we've been doing, we could just dump it in some alternate trash dimension where it's not gonna bother anybody! Probably!", price = 5e32, icon = {7,19}, tier = 10, building = "Portal", b1 = "Portal", order = 8.00489e2 },
	{ name = "Additional clock hands", desc = "Time machines are twice as efficient.", quote = "It seemed like a silly idea at first, but it turns out these have the strange ability to twist time in interesting new ways.", price = 7e33, icon = {8,19}, tier = 10, building = "Time machine", b1 = "Time machine", order = 9.0049e2 },
	{ name = "Baking Nobel prize", desc = "Antimatter condensers are twice as efficient.", quote = "What better way to sponsor scientific growth than to motivate those smarmy nerds with a meaningless award! What's more, each prize comes with a fine print lifelong exclusive contract to come work for you (or else)!", price = 8.5e34, icon = {13,19}, tier = 10, building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.000491e3 },
	{ name = "Reverse theory of light", desc = "Prisms are twice as efficient.", quote = "A whole new world of physics opens up when you decide that antiphotons are real and posit that light is merely a void in shadow.", price = 1.05e36, icon = {14,19}, tier = 10, building = "Prism", b1 = "Prism", order = 1.100492e3 },
	{ name = "Revised probabilistics", desc = "Chancemakers are twice as efficient.", quote = "Either something happens or it doesn't. That's a 50% chance! This suddenly makes a lot of unlikely things very possible.", price = 1.3e37, icon = {19,19}, tier = 10, building = "Chancemaker", b1 = "Chancemaker", order = 1.200493e3 },
	{ name = "Kitten analysts", desc = "You gain more CpS the more milk you have.", quote = "based on purrent return-on-investment meowdels we should be able to affurd to pay our empawyees somewhere around next century, sir", price = 9e41, icon = {18,30}, tier = 12, kitten = true, order = 2.0000494e4 },
	{ name = "Eye of the wrinkler", desc = "Mouse over a wrinkler to see how many cookies are in its stomach.", quote = "Just a wrinkler and its will to survive.Hangin' tough, stayin' hungry.", price = 99999999, icon = {27,26}, pool = "prestige", parents = {"Wrinkly cookies"}, posX = -417, posY = -997, order = 2.53006e2 },
	{ name = "Inspired checklist", desc = "Unlocks the Buy all feature, which lets you instantly purchase every upgrade in your store (starting from the cheapest one).Also unlocks the Vault, a store section where you can place upgrades you do not wish to auto-buy.", quote = "Snazzy grandma accessories? Check. Transdimensional abominations? Check. A bunch of eggs for some reason? Check. Machine that goes \"ping\"? Check and check.", price = 900000, icon = {28,26}, pool = "prestige", parents = {"Persistent memory","Permanent upgrade slot II"}, posX = 200, posY = 49, order = 1.41001e2 },
	{ name = "Pure pitch-black chocolate butter biscuit", desc = "Cookie production multiplier +10%.", quote = "Rewarded for owning 500 of everything.This chocolate is so pure and so flawless that it has no color of its own, instead taking on the appearance of whatever is around it. You're a bit surprised to notice that this one isn't stamped with your effigy, as its surface is perfectly smooth (to the picometer) - until you realize it's quite literally reflecting your own face like a mirror.", price = 1e53, icon = {24,27}, pool = "cookie", power = 10, order = 1.0300497e4 },
	{ name = "Chocolate oatmeal cookies", desc = "Cookie production multiplier +4%.", quote = "These bad boys compensate for lack of a cohesive form and a lumpy, unsightly appearance by being just simply delicious. Something we should all aspire to.", price = 5e35, icon = {23,28}, pool = "cookie", power = 4, unlockCookies = 2.5e34, order = 1.0020498e4 },
	{ name = "Molasses cookies", desc = "Cookie production multiplier +4%.", quote = "Sticky, crackly, and dusted in fine sugar.Some lunatics have been known to eat these with potatoes.", price = 1e36, icon = {24,28}, pool = "cookie", power = 4, unlockCookies = 5e34, order = 1.0020499e4 },
	{ name = "Biscotti", desc = "Cookie production multiplier +4%.", quote = "Almonds and pistachios make these very robust cookies slightly more interesting to eat than to bludgeon people with.", price = 5e36, icon = {22,28}, pool = "cookie", power = 4, unlockCookies = 2.5e35, order = 1.00205e4 },
	{ name = "Waffle cookies", desc = "Cookie production multiplier +4%.", quote = "Whether these are cookies with shockingly waffle-like features or simply regular cookie-sized waffles is a debate we're not getting into here.", price = 1e37, icon = {21,28}, pool = "cookie", power = 4, unlockCookies = 5e35, order = 1.0020501e4 },
	{ name = "Almond cookies", desc = "Cookie production multiplier +2%.", quote = "Sometimes you feel like one of these. Sometimes you don't.", price = 99999999, icon = {21,27}, pool = "cookie", power = 2, unlockCookies = 4.99999995e6, order = 1.0000502e4 },
	{ name = "Hazelnut cookies", desc = "Cookie production multiplier +2%.", quote = "Tastes like a morning stroll through a fragrant forest, minus the clouds of gnats.", price = 99999999, icon = {22,27}, pool = "cookie", power = 2, unlockCookies = 4.99999995e6, order = 1.0000503e4 },
	{ name = "Walnut cookies", desc = "Cookie production multiplier +2%.", quote = "Some experts have pointed to the walnut's eerie resemblance to the human brain as a sign of its sentience - a theory most walnuts vehemently object to.", price = 99999999, icon = {23,27}, pool = "cookie", power = 2, unlockCookies = 4.99999995e6, order = 1.0000504e4 },
	{ name = "Label printer", desc = "Mouse over an upgrade to see its tier.Note: only some upgrades have tiers. Tiers are purely cosmetic and have no effect on gameplay.", quote = "Also comes in real handy when you want to tell catsup apart from ketchup.", price = 5000000, icon = {28,29}, pool = "prestige", parents = {"Genius accounting"}, posX = 411, posY = -94, order = 505 },
	{ name = "Good manners", desc = "Grandmas are twice as efficient.", quote = "Apparently these ladies are much more amiable if you take the time to learn their strange, ancient customs, which seem to involve saying \"please\" and \"thank you\" and staring at the sun with bulging eyes while muttering eldritch curses under your breath.", price = 5e26, icon = {1,28}, tier = 11, building = "Grandma", b1 = "Grandma", order = 2.00506e2 },
	{ name = "Lindworms", desc = "Farms are twice as efficient.", quote = "You have to import these from far up north, but they really help aerate the soil!", price = 5.5e27, icon = {2,28}, tier = 11, building = "Farm", b1 = "Farm", order = 3.00507e2 },
	{ name = "Bore again", desc = "Mines are twice as efficient.", quote = "After extracting so much sediment for so long, you've formed some veritable mountains of your own from the accumulated piles of rock and dirt. Time to dig through those and see if you find anything fun!", price = 6e28, icon = {3,28}, tier = 11, building = "Mine", b1 = "Mine", order = 4.00508e2 },
	{ name = "\"Volunteer\" interns", desc = "Factories are twice as efficient.", quote = "If you're bad at something, always do it for free.", price = 6.5e29, icon = {4,28}, tier = 11, building = "Factory", b1 = "Factory", order = 5.00509e2 },
	{ name = "Rules of acquisition", desc = "Banks are twice as efficient.", quote = "Rule 387 : a cookie baked is a cookie kept.", price = 7e30, icon = {15,28}, tier = 11, building = "Bank", b1 = "Bank", order = 5.2551e2 },
	{ name = "War of the gods", desc = "Temples are twice as efficient.", quote = "An interesting game; the only winning move is not to pray.", price = 1e32, icon = {16,28}, tier = 11, building = "Temple", b1 = "Temple", order = 5.50511e2 },
	{ name = "Electricity", desc = "Wizard towers are twice as efficient.", quote = "Ancient magicks and forbidden hexes shroud this arcane knowledge, whose unfathomable power can mysteriously turn darkness into light and shock an elephant to death.", price = 1.65e33, icon = {17,28}, tier = 11, building = "Wizard tower", b1 = "Wizard tower", order = 5.75512e2 },
	{ name = "Universal alphabet", desc = "Shipments are twice as efficient.", quote = "You've managed to chart a language that can be understood by any sentient species in the galaxy; its exciting vocabulary contains over 56 trillion words that sound and look like sparkly burps, forming intricate sentences that usually translate to something like \"give us your cookies, or else\".", price = 2.55e34, icon = {5,28}, tier = 11, building = "Shipment", b1 = "Shipment", order = 6.00513e2 },
	{ name = "Public betterment", desc = "Alchemy labs are twice as efficient.", quote = "Why do we keep trying to change useless matter into cookies, or cookies into even better cookies? Clearly, the way of the future is to change the people who eat the cookies into people with a greater understanding, appreciation and respect for the cookies they're eating. Into the vat you go!", price = 3.75e35, icon = {6,28}, tier = 11, building = "Alchemy lab", b1 = "Alchemy lab", order = 7.00514e2 },
	{ name = "Embedded microportals", desc = "Portals are twice as efficient.", quote = "We've found out that if we bake the portals into the cookies themselves, we can transport people's taste buds straight into the taste dimension! Good thing your army of lawyers got rid of the FDA a while ago!", price = 5e36, icon = {7,28}, tier = 11, building = "Portal", b1 = "Portal", order = 8.00515e2 },
	{ name = "Nostalgia", desc = "Time machines are twice as efficient.", quote = "Your time machine technicians insist that this is some advanced new time travel tech, and not just an existing emotion universal to mankind. Either way, you have to admit that selling people the same old cookies just because it reminds them of the good old times is an interesting prospect.", price = 7e37, icon = {8,28}, tier = 11, building = "Time machine", b1 = "Time machine", order = 9.00516e2 },
	{ name = "The definite molecule", desc = "Antimatter condensers are twice as efficient.", quote = "Your scientists have found a way to pack a cookie into one single continuous molecule, opening exciting new prospects in both storage and flavor despite the fact that these take up to a whole year to digest.", price = 8.5e38, icon = {13,28}, tier = 11, building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.000517e3 },
	{ name = "Light capture measures", desc = "Prisms are twice as efficient.", quote = "As the universe gets ever so slightly dimmer due to you converting more and more of its light into cookies, you've taken to finding new and unexplored sources of light for your prisms; for instance, the warm glow emitted by a pregnant woman, or the twinkle in the eye of a hopeful child.", price = 1.05e40, icon = {14,28}, tier = 11, building = "Prism", b1 = "Prism", order = 1.100518e3 },
	{ name = "0-sided dice", desc = "Chancemakers are twice as efficient.", quote = "The advent of the 0-sided dice has had unexpected and tumultuous effects on the gambling community, and saw experts around the world calling you both a genius and an imbecile.", price = 1.3e41, icon = {19,28}, tier = 11, building = "Chancemaker", b1 = "Chancemaker", order = 1.200519e3 },
	{ name = "Heralds", desc = "You now benefit from the boost provided by heralds.Each herald gives you +1% CpS.Look on the purple flag at the top to see how many heralds are active at any given time.", quote = "World's first successful application of trickle-down economics!", price = 100, icon = {21,29}, pool = "prestige", parents = {"Legacy"}, posX = -317, posY = -26, order = 3.63001e2 },
	{ name = "Metagrandmas", desc = "Grandmas are twice as efficient. Fractal engines gain +1% CpS per 14 grandmas.", quote = "A fractal grandma to make more grandmas to make more cookies.", price = 1.55e19, icon = {10,9}, building = "Fractal engine", order = 2.55521e2 },
	{ name = "Metabakeries", desc = "Fractal engines are twice as efficient.", quote = "They practically bake themselves!", price = 3.1e18, icon = {20,0}, tier = 1, building = "Fractal engine", b1 = "Fractal engine", order = 1.300522e3 },
	{ name = "Mandelbrown sugar", desc = "Fractal engines are twice as efficient.", quote = "A substance that displays useful properties such as fractal sweetness and instant contact lethality.", price = 1.55e19, icon = {20,1}, tier = 2, building = "Fractal engine", b1 = "Fractal engine", order = 1.300523e3 },
	{ name = "Fractoids", desc = "Fractal engines are twice as efficient.", quote = "Here's a frun fract : all in all, these were a terrible idea.", price = 1.55e20, icon = {20,2}, tier = 3, building = "Fractal engine", b1 = "Fractal engine", order = 1.300524e3 },
	{ name = "Nested universe theory", desc = "Fractal engines are twice as efficient.", quote = "Asserts that each subatomic particle is host to a whole new universe, and therefore, another limitless quantity of cookies.This somehow stacks with the theory of nanocosmics, because physics.", price = 1.55e22, icon = {20,13}, tier = 4, building = "Fractal engine", b1 = "Fractal engine", order = 1.300525e3 },
	{ name = "Menger sponge cake", desc = "Fractal engines are twice as efficient.", quote = "Frighteningly absorbent thanks to its virtually infinite surface area. Keep it isolated in a dry chamber, never handle it with an open wound, and do not ever let it touch a body of water.", price = 1.55e24, icon = {20,14}, tier = 5, building = "Fractal engine", b1 = "Fractal engine", order = 1.300526e3 },
	{ name = "One particularly good-humored cow", desc = "Fractal engines are twice as efficient.", quote = "This unassuming bovine was excruciatingly expensive and it may seem at first like you were ripped off. On closer inspection however, you notice that its earrings (it's wearing earrings) are actually fully functional copies of itself, each of which also wearing their own cow earrings, and so on, infinitely. It appears your dairy concerns will be taken care of for a while, although you'll have to put up with the cow's annoying snickering.", price = 1.55e26, icon = {20,15}, tier = 6, building = "Fractal engine", b1 = "Fractal engine", order = 1.300527e3 },
	{ name = "Chocolate ouroboros", desc = "Fractal engines are twice as efficient.", quote = "Forever eating its own tail and digesting itself, in a metabolically dubious tale of delicious tragedy.", price = 1.55e29, icon = {20,16}, tier = 7, building = "Fractal engine", b1 = "Fractal engine", order = 1.300528e3 },
	{ name = "Nested", desc = "Fractal engines are twice as efficient.", quote = "Clever self-reference or shameful cross-promotion? This upgrade apparently has the gall to advertise a link to orteil.dashnet.org/nested, in a tooltip you can't even click.", price = 1.55e32, icon = {20,17}, tier = 8, building = "Fractal engine", b1 = "Fractal engine", order = 1.300529e3 },
	{ name = "Space-filling fibers", desc = "Fractal engines are twice as efficient.", quote = "This special ingredient has the incredible ability to fill the local space perfectly, effectively eradicating hunger in those who consume it!Knowing that no hunger means no need for cookies, your marketers urge you to repurpose this product into next-level packing peanuts.", price = 1.55e35, icon = {20,18}, tier = 9, building = "Fractal engine", b1 = "Fractal engine", order = 1.30053e3 },
	{ name = "Endless book of prose", desc = "Fractal engines are twice as efficient.", price = 1.55e38, icon = {20,19}, tier = 10, building = "Fractal engine", b1 = "Fractal engine", order = 1.300531e3 },
	{ name = "The set of all sets", desc = "Fractal engines are twice as efficient.", quote = "The answer, of course, is a definite maybe.", price = 1.55e42, icon = {20,28}, tier = 11, building = "Fractal engine", b1 = "Fractal engine", order = 1.300532e3 },
	{ name = "Recursive mirrors", desc = "Prisms gain +5% CpS per fractal engine.Fractal engines gain +0.1% CpS per prism.", quote = "Do you have any idea what happens when you point two of these at each other? Apparently, the universe doesn't either.", price = 6.62e22, icon = {20,20}, tier = "synergy1", b1 = "Prism", b2 = "Fractal engine", order = 5.000533e3 },
	{ name = "Mice clicking mice", desc = "Cursors gain +5% CpS per fractal engine.Fractal engines gain +0.1% CpS per cursor.", price = 6.2e28, icon = {20,29}, tier = "synergy2", b1 = "Cursor", b2 = "Fractal engine", order = 5.000534e3 },
	{ name = "Custard creams", desc = "Cookie production multiplier +4%.", quote = "British lore pits these in a merciless war against bourbon biscuits.The filling evokes vanilla without quite approaching it.They're tastier on the inside!", price = 5e37, icon = {23,29}, pool = "cookie", power = 4, unlockCookies = 2.5e36, order = 1.0020535e4 },
	{ name = "Bourbon biscuits", desc = "Cookie production multiplier +4%.", quote = "Two chocolate biscuits joined together with even more chocolate.The sworn rivals of custard creams, as legend has it.", price = 1e38, icon = {24,29}, pool = "cookie", power = 4, unlockCookies = 5e36, order = 1.0020536e4 },
	{ name = "Keepsakes", desc = "Seasonal random drops have a 1/5 chance to carry over through ascensions.", quote = "Cherish the memories.", price = 1111111111, icon = {22,29}, pool = "prestige", parents = {"Starsnow","Starlove","Starterror","Startrade","Starspawn"}, posX = -870, posY = -287, order = 1.81002e2 },
	{ name = "Mini-cookies", desc = "Cookie production multiplier +5%.", quote = "Have you ever noticed how the smaller something is, the easier it is to binge on it?", price = 5e38, icon = {29,30}, pool = "cookie", power = 5, unlockCookies = 2.5e37, order = 1.0020538e4 },
	{ name = "Sugar crystal cookies", desc = "Cookie production multiplier +5% permanently, and +1% for every building type level 10 or higher.", quote = "Infused with cosmic sweetness. It gives off a faint shimmery sound when you hold it up to your ear.", price = 1000000000, icon = {21,30}, pool = "prestige", powerFn = true, parents = {"Sugar baking"}, posX = -532, posY = -1166, order = 2.53008e2 },
	{ name = "Box of maybe cookies", desc = "Contains an assortment of...something.", quote = "These may or may not be considered cookies.", price = 333000000000, icon = {25,29}, pool = "prestige", parents = {"Sugar crystal cookies"}, posX = -598, posY = -1328, order = 2.53009e2 },
	{ name = "Box of not cookies", desc = "Contains an assortment of...something.", quote = "These are strictly, definitely not cookies.", price = 333000000000, icon = {26,29}, pool = "prestige", parents = {"Sugar crystal cookies"}, posX = -693, posY = -1234, order = 2.53009e2 },
	{ name = "Box of pastries", desc = "Contains an assortment of delicious pastries.", quote = "These are a damn slippery slope is what they are!", price = 333000000000, icon = {27,29}, pool = "prestige", parents = {"Sugar crystal cookies"}, posX = -465, posY = -1327, order = 2.53009e2 },
