	{ name = "Shimmering veil", desc = "Unlocks the shimmering veil, a switch that passively boosts your CpS by 50%.You start with the veil turned on; however, it is very fragile, and clicking the big cookie or any golden cookie or reindeer will turn it off, requiring 24 hours of CpS to turn back on.", quote = "Hands off!", price = 999999999, icon = {9,10}, pool = "prestige", parents = {"Distilled essence of redoubled luck"}, posX = -42, posY = 792, order = 2.82006e2 },
