	{ name = "Icebox cookies", desc = "Cookie production multiplier +5%.", quote = "Can be prepared in a variety of shapes with a variety of ingredients. Made by freezing dough before baking it, mirroring a time-proven medieval torture practice. Gotta keep them guessing.", price = 3.162277660168e41, icon = {26,31}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e40, order = 1.002057e4 },
