	{ name = "Hardtack", desc = "Cookie production multiplier +5%.", quote = "Extremely hard and, if we're being honest, extremely tack.If you're considering eating this as a fun snack, you probably have other things to worry about than this game, like getting scurvy or your crew fomenting mutiny.", price = 3.162277660168e42, icon = {28,31}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e41, order = 1.0020572e4 },
