	{ name = "Tofu cookies", desc = "Cookie production multiplier +5%.", quote = "There's really two ways to go with tofu cooking; either it asserts itself in plain sight or it camouflages itself in the other ingredients. This happens to be the latter, and as such, you can't really tell the difference between this and a regular cookie, save for that one pixel on the left.", price = 3.162277660168e43, icon = {30,31}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e42, order = 1.0020574e4 },
	{ name = "Gluten-free cookies", desc = "Cookie production multiplier +5%.", quote = "Made with browned butter and milk to closely match the archetypal chocolate chip cookie.For celiacs, a chance to indulge in a delicious risk-free pastry. For others, a strangely threatening confection whose empty eyes will never know heaven nor hell.", price = 3.162277660168e43, icon = {30,30}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e42, order = 1.0020575e4 },
	{ name = "Russian bread cookies", desc = "Cookie production multiplier +5%.", quote = "Also known as alphabet cookies; while most bakers follow the recipe to the letter, it is said that some substitute the flour for spelt. But don't take my word for it.", price = 1e44, icon = {30,29}, pool = "cookie", power = 5, unlockCookies = 5e42, order = 1.0020576e4 },
	{ name = "Lebkuchen", desc = "Cookie production multiplier +5%.", quote = "Diverse cookies from Germany, fragrant with honey and spices, often baked around Christmas.Once worn by warriors of old for protection in battle.+5 STR, +20% magic resistance.", price = 3.162277660168e44, icon = {30,28}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e43, order = 1.0020577e4 },
	{ name = "Aachener Printen", desc = "Cookie production multiplier +5%.", quote = "The honey once used to sweeten these gingerbread-like treats has since been swapped out for beet sugar, providing another sad example of regressive evolution.", price = 1e45, icon = {30,27}, pool = "cookie", power = 5, unlockCookies = 5e43, order = 1.0020578e4 },
