	{ name = "Nice biscuits", desc = "Cookie production multiplier +5%.", quote = "Made with coconut and perfect with tea. Traces its origins to a French city so nice they named it that.", price = 1e46, icon = {30,25}, pool = "cookie", power = 5, unlockCookies = 5e44, order = 1.002058e4 },
	{ name = "French pure butter cookies", desc = "Cookie production multiplier +5%.", quote = "You can't tell what's stronger coming off these - the smell of butter or condescension.", price = 3.162277660168e46, icon = {31,25}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e45, order = 1.0020581e4 },
