	{ name = "Candy", desc = "Cookie production multiplier +5%.", quote = "There are two pillars to the world of sweets: pastries, of course - and candy.You could make a whole new game just about these, but for now, please enjoy these assorted generic treats.", price = 1e46, icon = {30,10}, pool = "cookie", power = 5, unlockCookies = 5e44, unlockRequire = "Box of not cookies", order = 1.006062e4 },
