	{ name = "Fortune #002", desc = "Grandmas are 7% more efficient and 7% cheaper.", quote = "A wrinkle is a crack in a mundane facade.", price = 7.777777777778e30, icon = {1,32}, tier = "fortune", building = "Grandma", b1 = "Grandma", order = 1.9000622e4 },
	{ name = "Fortune #003", desc = "Farms are 7% more efficient and 7% cheaper.", quote = "The seeds of tomorrow already lie within the seeds of today.", price = 8.555555555556e31, icon = {2,32}, tier = "fortune", building = "Farm", b1 = "Farm", order = 1.9000623e4 },
	{ name = "Fortune #004", desc = "Mines are 7% more efficient and 7% cheaper.", quote = "Riches from deep under elevate you all the same.", price = 9.333333333333e32, icon = {3,32}, tier = "fortune", building = "Mine", b1 = "Mine", order = 1.9000624e4 },
	{ name = "Fortune #005", desc = "Factories are 7% more efficient and 7% cheaper.", quote = "True worth is not in what you find, but in what you make.", price = 1.011111111111e34, icon = {4,32}, tier = "fortune", building = "Factory", b1 = "Factory", order = 1.9000625e4 },
	{ name = "Fortune #006", desc = "Banks are 7% more efficient and 7% cheaper.", quote = "The value of money means nothing to a pocket.", price = 1.088888888889e35, icon = {15,32}, tier = "fortune", building = "Bank", b1 = "Bank", order = 1.9000626e4 },
	{ name = "Fortune #007", desc = "Temples are 7% more efficient and 7% cheaper.", quote = "Not all guides deserve worship.", price = 1.555555555556e36, icon = {16,32}, tier = "fortune", building = "Temple", b1 = "Temple", order = 1.9000627e4 },
	{ name = "Fortune #008", desc = "Wizard towers are 7% more efficient and 7% cheaper.", quote = "Magic is about two things - showmanship, and rabbits.", price = 2.566666666667e37, icon = {17,32}, tier = "fortune", building = "Wizard tower", b1 = "Wizard tower", order = 1.9000628e4 },
	{ name = "Fortune #009", desc = "Shipments are 7% more efficient and 7% cheaper.", quote = "Every mile travelled expands the mind by just as much.", price = 3.966666666667e38, icon = {5,32}, tier = "fortune", building = "Shipment", b1 = "Shipment", order = 1.9000629e4 },
	{ name = "Fortune #010", desc = "Alchemy labs are 7% more efficient and 7% cheaper.", quote = "Change what you cannot accept. Furthermore: accept nothing.", price = 5.833333333333e39, icon = {6,32}, tier = "fortune", building = "Alchemy lab", b1 = "Alchemy lab", order = 1.900063e4 },
	{ name = "Fortune #011", desc = "Portals are 7% more efficient and 7% cheaper.", quote = "Every doorway is a gamble. Tread with care.", price = 7.777777777778e40, icon = {7,32}, tier = "fortune", building = "Portal", b1 = "Portal", order = 1.9000631e4 },
	{ name = "Fortune #012", desc = "Time machines are 7% more efficient and 7% cheaper.", quote = "Do your future self a favor; they'll thank you for it.", price = 1.088888888889e42, icon = {8,32}, tier = "fortune", building = "Time machine", b1 = "Time machine", order = 1.9000632e4 },
	{ name = "Fortune #013", desc = "Antimatter condensers are 7% more efficient and 7% cheaper.", quote = "The world is made of what we put into it.", price = 1.322222222222e43, icon = {13,32}, tier = "fortune", building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.9000633e4 },
	{ name = "Fortune #014", desc = "Prisms are 7% more efficient and 7% cheaper.", quote = "Staring at a dazzling light can blind you back to darkness.", price = 1.633333333333e44, icon = {14,32}, tier = "fortune", building = "Prism", b1 = "Prism", order = 1.9000634e4 },
	{ name = "Fortune #015", desc = "Chancemakers are 7% more efficient and 7% cheaper.", quote = "Don't leave to blind chance what you could accomplish with deaf skill.", price = 2.022222222222e45, icon = {19,32}, tier = "fortune", building = "Chancemaker", b1 = "Chancemaker", order = 1.9000635e4 },
	{ name = "Fortune #016", desc = "Fractal engines are 7% more efficient and 7% cheaper.", quote = "It's good to see yourself in others. Remember to see yourself in yourself, too.", price = 2.411111111111e46, icon = {20,32}, tier = "fortune", building = "Fractal engine", b1 = "Fractal engine", order = 1.9000636e4 },
	{ name = "Fortune #017", desc = "Javascript consoles are 7% more efficient and 7% cheaper.", quote = "If things aren't working out for you, rewrite the rules.", price = 5.522222222222e48, icon = {32,32}, tier = "fortune", building = "Javascript console", b1 = "Javascript console", order = 1.9000637e4 },
	{ name = "Fortune #100", desc = "All buildings and upgrades are 1% cheaper. Cookie production multiplier +1%.", quote = "True wealth is counted in gifts.", price = 7.777777777778e33, icon = {10,32}, tier = "fortune", order = 1.9100638e4 },
	{ name = "Fortune #101", desc = "Cookie production multiplier +7%.", quote = "Some people dream of fortunes; others dream of cookies.", price = 7.777777777778e36, icon = {10,32}, tier = "fortune", order = 1.9100639e4 },
	{ name = "Fortune #102", desc = "You gain another +1% of your regular CpS while the game is closed. (Must own the Twin Gates of Transcendence upgrade.)", quote = "Help, I'm trapped in a browser game!", price = 7.777777777778e39, icon = {10,32}, tier = "fortune", order = 1.910064e4 },
	{ name = "Fortune #103", desc = "You gain more CpS the more milk you have.", quote = "Don't believe the superstitions; all cats are good luck.", price = 7.777777777778e42, icon = {18,32}, tier = "fortune", kitten = true, order = 1.9100641e4 },
	{ name = "Fortune #104", desc = "Clicking gains +1% of your CpS.", quote = "Remember to stay in touch.", price = 7.777777777778e39, icon = {11,32}, tier = "fortune", order = 1.9100642e4 },
	{ name = "Fortune cookies", desc = "The news ticker may occasionally have fortunes, which may be clicked for something good.", quote = "These don't taste all that great but that's not really the point, is it?", price = 77777777777, icon = {29,8}, pool = "prestige", parents = {"Distilled essence of redoubled luck"}, posX = -293, posY = 770, order = 2.82006e2 },
	{ name = "A really good guide book", desc = "???", quote = "??????", price = 7, icon = {22,12}, pool = "debug", order = 4.0000644e4 },
	{ name = "Prism heart biscuits", desc = "Cookie production multiplier +2%.", quote = "An every-flavor biscuit that stands for universal love and being true to yourself.", price = 1e24, icon = {30,8}, pool = "cookie", powerFn = true, unlockCookies = 5e22, unlockRequire = "Eternal heart biscuits", unlockSeason = "valentines", order = 1.0300175e4 },
	{ name = "Kitten wages", desc = "Through clever accounting, this actually makes kitten upgrades 10% cheaper.", quote = "Cats can have little a salary, as a treat.Cats are expert hagglers and have a keen sense of bargaining, especially in the case of cash.", price = 9000000000, icon = {31,8}, pool = "prestige", kitten = true, parents = {"Kitten angels"}, posX = 485, posY = -882, order = 2.74005e2 },
	{ name = "Pet the dragon", desc = "Unlocks the ability to pet your dragon by clicking on it once hatched.", quote = "Dragons do not purr. If your dragon starts purring, vacate the area immediately.", price = 99999999999, icon = {30,12}, pool = "prestige", parents = {"How to bake your dragon","Residual luck"}, posX = -118, posY = 248, order = 3.23001e2 },
	{ name = "Dragon scale", desc = "Cookie production multiplier +3%.Cost scales with CpS, but 10 times cheaper with a fully-trained dragon.", quote = "Your dragon sheds these regularly, so this one probably won't be missed.Note: icon not to scale.", price = 0, icon = {30,14}, order = 2.5100648e4 },
	{ name = "Dragon claw", desc = "Clicking is 3% more powerful.Cost scales with CpS, but 10 times cheaper with a fully-trained dragon.", quote = "Will grow back in a few days' time.A six-inch retractable claw, like a razor, from the middle toe. So you know, try to show a little respect.", price = 0, icon = {31,14}, order = 2.5100649e4 },
	{ name = "Dragon fang", desc = "Golden cookies give 3% more cookies.Dragon harvest and Dragonflight are 10% stronger.Cost scales with CpS, but 10 times cheaper with a fully-trained dragon.", quote = "Just a fallen baby tooth your dragon wanted you to have, as a gift.It might be smaller than an adult tooth, but it's still frighteningly sharp - and displays some awe-inspiring cavities, which you might expect from a creature made out of sweets.", price = 0, icon = {30,15}, order = 2.510065e4 },
	{ name = "Dragon teddy bear", desc = "Random drops are 3% more common.Cost scales with CpS, but 10 times cheaper with a fully-trained dragon.", quote = "Your dragon used to sleep with this, but it's yours now.Crafted in the likeness of a fearsome beast. Stuffed with magical herbs picked long ago by a wandering wizard. Woven from elven yarn and a polyester blend.", price = 0, icon = {31,15}, order = 2.5100651e4 },
	{ name = "Granola cookies", desc = "Cookie production multiplier +5%.", quote = "Wait! These are just oatmeal cookies mixed with raisin cookies! What next, half-dark chocolate half-white chocolate cookies?", price = 3.162277660168e52, icon = {28,32}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e51, order = 1.0020652e4 },
	{ name = "Ricotta cookies", desc = "Cookie production multiplier +5%.", quote = "Light and cake-like. Often flavored with lemon or almond extract. Sprinkles optional. Allegedly Italian. Investigation pending.", price = 1e53, icon = {29,32}, pool = "cookie", power = 5, unlockCookies = 5e51, order = 1.0020653e4 },
	{ name = "Roze koeken", desc = "Cookie production multiplier +5%.", quote = "The icing on these Dutch cookies is traditionally pink, but different colors may be used for special occasions - such as pink to celebrate Breast Cancer Awareness Month, or for International Flamingo Day, pink.", price = 3.162277660168e53, icon = {30,32}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e52, order = 1.0020654e4 },
	{ name = "Peanut butter cup cookies", desc = "Cookie production multiplier +5%.", quote = "What more poignant example of modern societal struggles than the brazen reclaiming of a corporate product by integrating it in the vastly more authentic shell of a homemade undertaking? Anyway this is a peanut butter cup, baked into a cookie. It's pretty good!", price = 1e54, icon = {31,32}, pool = "cookie", power = 5, unlockCookies = 5e52, order = 1.0020655e4 },
	{ name = "Sesame cookies", desc = "Cookie production multiplier +5%.", quote = "Look at all the little seeds on these! It's like someone dropped them on the street or something! A very welcoming and educational street!", price = 3.162277660168e54, icon = {22,33}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e53, order = 1.0020656e4 },
	{ name = "Taiyaki", desc = "Cookie production multiplier +5%.", quote = "A pastry fish filled with red bean paste, doomed to live an existence of constant and excruciating pain as its aquatic environment slowly dissolves its soft doughy body.Also comes in chocolate flavor!", price = 1e55, icon = {23,33}, pool = "cookie", power = 5, unlockCookies = 5e53, order = 1.0020657e4 },
	{ name = "Vanillekipferl", desc = "Cookie production multiplier +5%.", quote = "Nut-based cookies from Central Europe, coated in powdered vanilla sugar. Regular kipferl, crescent-shaped bread rolls from the same region, are much less exciting.", price = 3.162277660168e55, icon = {24,33}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e54, order = 1.0020658e4 },
	{ name = "Cosmic chocolate butter biscuit", desc = "Cookie production multiplier +10%.", quote = "Rewarded for owning 550 of everything.Through some strange trick of magic or technology, looking at this cookie is like peering into a deep ocean of ancient stars. The origins of this biscuit are unknown; its manufacture, as far as your best investigators can tell, left no paper trail. From a certain angle, if you squint hard enough, you'll notice that a number of stars near the center are arranged to resemble the outline of your own face.", price = 1e56, icon = {27,32}, pool = "cookie", power = 10, order = 1.0300659e4 },
	{ name = "Nonillion fingers", desc = "Multiplies the gain from Thousand fingers by 20.", quote = "Only for the freakiest handshakes.", price = 1e25, icon = {0,31}, tier = 13, order = 1.0066e2 },
	{ name = "Miraculite mouse", desc = "Clicking gains +1% of your CpS.", quote = "Composed of a material that neither science nor philosophy are equipped to conceptualize. And boy, does it ever click.", price = 5e28, icon = {11,31}, tier = 13, order = 1.50661e2 },
	{ name = "Generation degeneration", desc = "Grandmas are twice as efficient.", quote = "Genetic testing shows that most of your grandmas are infected with a strange degenerative disease that only seems to further their powers; the more time passes, the older they get. This should concern you.", price = 5e30, icon = {1,30}, tier = 12, building = "Grandma", b1 = "Grandma", order = 2.00662e2 },
	{ name = "Global seed vault", desc = "Farms are twice as efficient.", quote = "An enormous genetic repository that could outlive an apocalypse. Guarantees the survival of your empire, or at the very least its agricultural components, should civilization fall. Which should be any day now.", price = 5.5e31, icon = {2,30}, tier = 12, building = "Farm", b1 = "Farm", order = 3.00663e2 },
	{ name = "Air mining", desc = "Mines are twice as efficient.", quote = "You've dug your drills through just about every solid surface you could find. But did you know recent advances have revealed untold riches hiding within non-solid surfaces too?", price = 6e32, icon = {3,30}, tier = 12, building = "Mine", b1 = "Mine", order = 4.00664e2 },
	{ name = "Behavioral reframing", desc = "Factories are twice as efficient.", quote = "Through careful social engineering you've convinced your workers that \"union\" is a slur that only the most vile and repugnant filth among us would ever dare utter! Sometimes progress isn't in the big machines, it's in the little lies!", price = 6.5e33, icon = {4,30}, tier = 12, building = "Factory", b1 = "Factory", order = 5.00665e2 },
	{ name = "Altruistic loop", desc = "Banks are twice as efficient.", quote = "You control so many branches of the global economy and legislative bodies that, through a particularly creative loophole, donating money (to yourself) grants you even more cash in tax deductions than you started with!", price = 7e34, icon = {15,30}, tier = 12, building = "Bank", b1 = "Bank", order = 5.25666e2 },
	{ name = "A novel idea", desc = "Temples are twice as efficient.", quote = "You don't get rich starting a religion. If you want to get rich, you write science fiction.", price = 1e36, icon = {16,30}, tier = 12, building = "Temple", b1 = "Temple", order = 5.50667e2 },
	{ name = "Spelling bees", desc = "Wizard towers are twice as efficient.", quote = "You've unleashed a swarm of magically-enhanced bees upon mankind! Their stinging spells may be the bane of all living things but you're certain you can put their delicious, purple, fizzy honey to good use!", price = 1.65e37, icon = {17,30}, tier = 12, building = "Wizard tower", b1 = "Wizard tower", order = 5.75668e2 },
	{ name = "Toroid universe", desc = "Shipments are twice as efficient.", quote = "If you think of the universe as an nth-dimensional torus that wraps back on itself in every direction, you can save a fortune on rocket fuel! Of course the universe isn't actually shaped like that, but you've never let details stand in your way.", price = 2.55e38, icon = {5,30}, tier = 12, building = "Shipment", b1 = "Shipment", order = 6.00669e2 },
	{ name = "Hermetic reconciliation", desc = "Alchemy labs are twice as efficient.", quote = "It's time for modern science and the mystical domains of the occult to work together at last. What do gravitons transmute into? What if alkahest is pH-neutral? Should a homunculus have the right to vote? And other exciting questions coming to you soon, whether you like it or not.", price = 3.75e39, icon = {6,30}, tier = 12, building = "Alchemy lab", b1 = "Alchemy lab", order = 7.0067e2 },
	{ name = "His advent", desc = "Portals are twice as efficient.", quote = "He comes! He comes at last! Just like the prophecies foretold! And as He steps out of the portal, your engineers begin slicing Him into convenient chunks before transporting His writhing cosmic flesh to your factories, where He will be processed and converted into a new and exciting cookie flavor, available in stores tomorrow.", price = 5e40, icon = {7,30}, tier = 12, building = "Portal", b1 = "Portal", order = 8.00671e2 },
	{ name = "Split seconds", desc = "Time machines are twice as efficient.", quote = "Time is infinite, yes... But what if, nestled within each second, were even more infinities? Every moment an eternity! Think of how many scheduling troubles this solves!", price = 7e41, icon = {8,30}, tier = 12, building = "Time machine", b1 = "Time machine", order = 9.00672e2 },
	{ name = "Flavor itself", desc = "Antimatter condensers are twice as efficient.", quote = "Deep under the earth, in the most sterile laboratory, in the most vast and expensive particle accelerator ever devised, your scientists have synthesized -for a fraction of a second- the physical manifestation of pure flavor. Highly unstable, and gone in a puff of radioactive energy, it nonetheless left your team shivering with awe... and hunger.", price = 8.5e42, icon = {13,30}, tier = 12, building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.000673e3 },
	{ name = "Light speed limit", desc = "Prisms are twice as efficient.", quote = "Whoah, slow down. Harvesting light is well and good but it'd be much easier if it weren't so dang fast! This should thankfully take care of that.", price = 1.05e44, icon = {14,30}, tier = 12, building = "Prism", b1 = "Prism", order = 1.100674e3 },
	{ name = "A touch of determinism", desc = "Chancemakers are twice as efficient.", quote = "By knowing the exact position and movement of every particle in the universe, you're able to predict everything that can ever happen, leaving nothing to chance. This was a doozy to pull off mind you, but it's helped you win 50 bucks at the horse races so you could say it's already paying off.", price = 1.3e45, icon = {19,30}, tier = 12, building = "Chancemaker", b1 = "Chancemaker", order = 1.200675e3 },
	{ name = "This upgrade", desc = "Fractal engines are twice as efficient.", quote = "This upgrade's flavor text likes to refer to itself, as well as to the fact that it likes to refer to itself. You should really buy this upgrade before it starts doing anything more obnoxious.", price = 1.55e46, icon = {20,30}, tier = 12, building = "Fractal engine", b1 = "Fractal engine", order = 1.300676e3 },
	{ name = "Your biggest fans", desc = "Javascript consoles are twice as efficient.", quote = "Let's face it, baking cookies isn't the most optimized thing there is. So you've purchased your biggest fans yet and stuck them next to your computers to keep things chill and in working order. Cool!", price = 3.55e48, icon = {32,30}, tier = 12, building = "Javascript console", b1 = "Javascript console", order = 1.400677e3 },
	{ name = "Battenberg biscuits", desc = "Cookie production multiplier +5%.", quote = "Inspired by a cake of the same name, itself named after a prince of the same name. You suppose you could play a really, really short game of chess on these.", price = 1e56, icon = {28,33}, pool = "cookie", power = 5, unlockCookies = 5e54, order = 1.0020678e4 },
	{ name = "Rosette cookies", desc = "Cookie production multiplier +5%.", quote = "Intricate fried pastries from Northern Europe, made using specialized irons and dipped in icing sugar. While usually eaten as a delicious treat, these are often also used as Christmas tree decorations, or worn elegantly on one's lapel to symbolize the nah I'm just messing with you.", price = 3.162277660168e56, icon = {26,33}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e55, order = 1.0020679e4 },
	{ name = "Gangmakers", desc = "Cookie production multiplier +5%.", quote = "The little bit of raspberry jam at its center is crucial; a plain butter cookie with chocolate topping does not a gangmaker make.", price = 1e57, icon = {27,33}, pool = "cookie", power = 5, unlockCookies = 5e55, order = 1.002068e4 },
	{ name = "Welsh cookies", desc = "Cookie production multiplier +5%.", quote = "Welsh cookies, also known as Welsh cakes, bakestones, griddle cakes, griddle scones, or pics, or in Welsh: picau ar y maen, pice bach, cacennau cri or teisennau gradell, are rich currant-filled scone-like biscuits of uncertain origin.", price = 3.162277660168e57, icon = {29,33}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e56, order = 1.0020681e4 },
	{ name = "Raspberry cheesecake cookies", desc = "Cookie production multiplier +5%.", quote = "The humble raspberry cheesecake, now in ascended cookie form. Researchers posit that raspberry cheesecake cookies are evidence that the final form of every baked good, through convergent evolution, approaches that of a cookie, in a process known as cookienisation.", price = 1e58, icon = {25,33}, pool = "cookie", power = 5, unlockCookies = 5e56, order = 1.0020682e4 },
	{ name = "Alternate grandmas", desc = "Grandmas are twice as efficient. Idleverses gain +1% CpS per 16 grandmas.", quote = "A different grandma to bake something else.", price = 6e23, icon = {10,9}, building = "Idleverse", order = 2.55683e2 },
	{ name = "Manifest destiny", desc = "Idleverses are twice as efficient.", quote = "While the ethics of ransacking parallel universes for their riches may seem questionable to some, you've reasoned that bringing the good word of your cookie empire to the unwashed confines of other realities is your moral duty, nay, your righteous imperative, and must be undertaken as soon as possible, lest they do it to you first!", price = 1.2e23, icon = {33,0}, tier = 1, building = "Idleverse", b1 = "Idleverse", order = 1.500684e3 },
	{ name = "The multiverse in a nutshell", desc = "Idleverses are twice as efficient.", quote = "The structure of the metacosmos may seem confusing and at times even contradictory, but here's what you've gathered so far:- each reality, or \"idleverse\", exists in parallel to all others- most realities seem to converge towards the production of a sole type of item (ours evidently being, thanks to you, cookies)- each reality is riddled with chaotic tunnels to a number of subordinate dimensions (such as the so-called \"cookieverse\"), much like swiss cheese- all realities bathe in an infinite liquid of peculiar properties, colloquially known as \"milk\"Finally, each reality may have its own interpretation of the concept of \"reality\", for added fun.", price = 6e23, icon = {33,1}, tier = 2, building = "Idleverse", b1 = "Idleverse", order = 1.500685e3 },
	{ name = "All-conversion", desc = "Idleverses are twice as efficient.", quote = "It's quite nice that you can rewire the logic of each universe to generate cookies instead, but you still end up with parsec-loads of whatever they were producing before - baubles you've long made obsolete: cash money, gems, cheeseburgers, puppies... That's why you've designed the universal converter, compatible with any substance and capable of turning those useless spoils of conquest into the reassuring crumbly rustle of even more cookies.", price = 6e24, icon = {33,2}, tier = 3, building = "Idleverse", b1 = "Idleverse", order = 1.500686e3 },
	{ name = "Multiverse agents", desc = "Idleverses are twice as efficient.", quote = "You can send undercover spies to infiltrate each universe and have them signal you whether it's worth overtaking. Once the assimilation process started, they will also help pacify the local populations, having established trust through the use of wacky, but seamless, disguises.", price = 6e26, icon = {33,13}, tier = 4, building = "Idleverse", b1 = "Idleverse", order = 1.500687e3 },
	{ name = "Escape plan", desc = "Idleverses are twice as efficient.", quote = "You've set an idleverse aside and terraformed it to closely resemble this one in case something goes horribly wrong in here. Of course, the denizens of that idleverse also have their own escape idleverse to abscond to in the eventuality of your arrival, itself likely having its own contingency idleverse, and so on.", price = 6e28, icon = {33,14}, tier = 5, building = "Idleverse", b1 = "Idleverse", order = 1.500688e3 },
	{ name = "Game design", desc = "Idleverses are twice as efficient.", quote = "Each idleverse functions according to some form of transcendental programming, that much is a given. But they also seem to be governed by much more subtle rules, the logic of which, when harnessed, may give you unparalleled dominion over the multiverse. Rewrite the rules! A game designer is you!", price = 6e30, icon = {33,15}, tier = 6, building = "Idleverse", b1 = "Idleverse", order = 1.500689e3 },
	{ name = "Sandbox universes", desc = "Idleverses are twice as efficient.", quote = "It doesn't seem like you'll run out of extra universes anytime soon so why not repurpose some of them as consequence-free testing grounds for all your more existentially threatening market research? (...consequence-free for you, anyway.)", price = 6e33, icon = {33,16}, tier = 7, building = "Idleverse", b1 = "Idleverse", order = 1.50069e3 },
	{ name = "Multiverse wars", desc = "Idleverses are twice as efficient.", quote = "Hmm, looks like some other universes wised up to your plundering. Thankfully, that's nothing your extra beefed-up metacosmic military budget can't handle!", price = 6e36, icon = {33,17}, tier = 8, building = "Idleverse", b1 = "Idleverse", order = 1.500691e3 },
	{ name = "Mobile ports", desc = "Idleverses are twice as efficient.", quote = "Accessing each outer universe is a bit of a hassle, requiring the once-in-a-blue-moon alignment of natural cosmic ports to transit from universe to universe. You've finally perfected the method of constructing your own self-propelled ports, which can travel near-instantaneously along universal perimeters to permit headache-free multiverse connections. Took you long enough.", price = 6e39, icon = {33,18}, tier = 9, building = "Idleverse", b1 = "Idleverse", order = 1.500692e3 },
	{ name = "Encapsulated realities", desc = "Idleverses are twice as efficient.", quote = "Untold feats of science went into the reduction of infinite universes into these small, glimmering, easy-to-store little spheres. Exercise infinite caution when handling these, for each of them, containing endless galaxies and supporting endless life, is more precious than you can ever fathom. They've also proven to be quite a smash hit in your warehouses on bowling night.", price = 6e42, icon = {33,19}, tier = 10, building = "Idleverse", b1 = "Idleverse", order = 1.500693e3 },
	{ name = "Extrinsic clicking", desc = "Idleverses are twice as efficient.", quote = "If you poke an idleverse, it seems like it gets work done faster. It's also quite fun hearing a trillion terrified voices screaming in unison.", price = 6e46, icon = {33,28}, tier = 11, building = "Idleverse", b1 = "Idleverse", order = 1.500694e3 },
	{ name = "Universal idling", desc = "Idleverses are twice as efficient.", quote = "The nature of idleverses is found in waiting. The more you wait on an idleverse, the more exponentially potent it becomes - which saves you a whole lot of hard work. In a true act of zen, you've taken to biding your time when collecting new universes, letting them ripen like a fine wine.", price = 6e50, icon = {33,30}, tier = 12, building = "Idleverse", b1 = "Idleverse", order = 1.500695e3 },
	{ name = "Perforated mille-feuille cosmos", desc = "Portals gain +5% CpS per idleverse.Idleverses gain +0.1% CpS per portal.", quote = "Imagine, if you will, layers upon layers upon layers. Now picture billions of worms chewing their way through it all. This roughly, but not quite, approximates the geometry of the most basal stratum of our natural world.", price = 2.400000002e27, icon = {33,20}, tier = "synergy1", b1 = "Portal", b2 = "Idleverse", order = 5.000696e3 },
	{ name = "Infraverses and superverses", desc = "Fractal engines gain +5% CpS per idleverse.Idleverses gain +0.1% CpS per fractal engine.", quote = "Universes within universes? How subversive!", price = 2.40062e33, icon = {33,29}, tier = "synergy2", b1 = "Fractal engine", b2 = "Idleverse", order = 5.000697e3 },
	{ name = "Fortune #018", desc = "Idleverses are 7% more efficient and 7% cheaper.", quote = "There's plenty of everyone, but only one of you.", price = 9.333333333333e50, icon = {33,32}, tier = "fortune", building = "Idleverse", b1 = "Idleverse", order = 1.9000698e4 },
	{ name = "Butter biscuit (with butter)", desc = "Cookie production multiplier +10%.", quote = "Rewarded for owning 600 of everything.This is a plain butter biscuit. It's got some butter on it. The butter doesn't look like anything in particular.", price = 1e59, icon = {30,33}, pool = "cookie", power = 10, order = 1.0300699e4 },
	{ name = "Visits", desc = "Grandmas are twice as efficient.", quote = "In an extensive double-blind study (sample size: 12 million), your researchers have found evidence that grandmas are up to twice as productive if you just come by and say hi once in a while. It's nice to check up on your grans! (Do not under any circumstances ingest any tea or tea-like substances the grandmas may offer you.)", price = 5e34, icon = {1,31}, tier = 13, building = "Grandma", b1 = "Grandma", order = 2.007e2 },
	{ name = "Reverse-veganism", desc = "Farms are twice as efficient.", quote = "Plants aren't for eating, plants are for exploitative agriculture and astronomical profit margins!", price = 5.5e35, icon = {2,31}, tier = 13, building = "Farm", b1 = "Farm", order = 3.00701e2 },
	{ name = "Caramel alloys", desc = "Mines are twice as efficient.", quote = "Your geologists have isolated a family of once-overlooked sugary ores that, when combined, may be turned into even more cookie ingredients. Your millions of miles of previously useless tunnels probably house insane amounts of the stuff!", price = 6e36, icon = {3,31}, tier = 13, building = "Mine", b1 = "Mine", order = 4.00702e2 },
	{ name = "The infinity engine", desc = "Factories are twice as efficient.", quote = "In this house, I guess we don't care much for the laws of thermodynamics.", price = 6.5e37, icon = {4,31}, tier = 13, building = "Factory", b1 = "Factory", order = 5.00703e2 },
	{ name = "Diminishing tax returns", desc = "Banks are twice as efficient.", quote = "Wow, they're tiny! Wish you'd thought of that sooner!", price = 7e38, icon = {15,31}, tier = 13, building = "Bank", b1 = "Bank", order = 5.25704e2 },
	{ name = "Apparitions", desc = "Temples are twice as efficient.", quote = "You've booked a deal with the higher-ups that schedules one weekly earthly apparition by a deity, angel, ascended prophet, or other holy figure. This should boost interest in cookie religion among youths as long as you can secure a decent time slot.", price = 1e40, icon = {16,31}, tier = 13, building = "Temple", b1 = "Temple", order = 5.50705e2 },
	{ name = "Wizard basements", desc = "Wizard towers are twice as efficient.", quote = "You've received construction permits allowing you to build basements underneath each wizard tower. This provides a handy storage space for precious reagents, fizzled-out soul gems, and weird old magazines.", price = 1.65e41, icon = {17,31}, tier = 13, building = "Wizard tower", b1 = "Wizard tower", order = 5.75706e2 },
	{ name = "Prime directive", desc = "Shipments are twice as efficient.", quote = "An intergalactic delegation made you pinky-swear not to directly interact with lesser alien cultures. Which is fine, because it's much funnier to rob a planet blind when its inhabitants have no idea what's going on.", price = 2.55e42, icon = {5,31}, tier = 13, building = "Shipment", b1 = "Shipment", order = 6.00707e2 },
	{ name = "Chromatic cycling", desc = "Alchemy labs are twice as efficient.", quote = "All states of matter exist in a continuous loop. Having learned how to cycle through them, all you have to do is to freeze matter right on the state you need. For reference, the cookie state of matter is situated at precisely 163.719&deg;, right between lamellar gas and metaplasma.", price = 3.75e43, icon = {6,31}, tier = 13, building = "Alchemy lab", b1 = "Alchemy lab", order = 7.00708e2 },
	{ name = "Domestic rifts", desc = "Portals are twice as efficient.", quote = "You've managed to manufacture portals that are convenient enough, and legally safe enough, that you can just stick them against walls inside buildings to connect rooms together in unusual configurations. In practice, this means your employees get to have much shorter bathroom breaks.", price = 5e44, icon = {7,31}, tier = 13, building = "Portal", b1 = "Portal", order = 8.00709e2 },
	{ name = "Patience abolished", desc = "Time machines are twice as efficient.", quote = "You wait for no one.", price = 7e45, icon = {8,31}, tier = 13, building = "Time machine", b1 = "Time machine", order = 9.0071e2 },
	{ name = "Delicious pull", desc = "Antimatter condensers are twice as efficient.", quote = "In addition to the 4 fundamental forces of the universe -gravity, electromagnetism, weak and strong interactions- your scientists have at long last confirmed the existence of a fifth one, mediated by sugar bosons; it dictates that any two masses of ingredient-like matter will, given enough time, eventually meet each other to produce a third, even tastier substance. Your team enthusiastically names it the delicious pull.", price = 8.5e46, icon = {13,31}, tier = 13, building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.000711e3 },
	{ name = "Occam's laser", desc = "Prisms are twice as efficient.", quote = "Invented by Franciscan friar William of Occam in 1327. An impossibly clever use of light theory with a billion possible applications, some of which frightfully destructive. Confined to a single goat-skin parchment for hundreds of years until the patent expired and hit public domain, just now.", price = 1.05e48, icon = {14,31}, tier = 13, building = "Prism", b1 = "Prism", order = 1.100712e3 },
	{ name = "On a streak", desc = "Chancemakers are twice as efficient.", quote = "Take a moment to appreciate how far you've come. How lucky you've been so far. It doesn't take a genius statistician to extrapolate a trend from this. There's no way anything bad could happen to you now. Right?", price = 1.3e49, icon = {19,31}, tier = 13, building = "Chancemaker", b1 = "Chancemaker", order = 1.200713e3 },
	{ name = "A box", desc = "Fractal engines are twice as efficient.", quote = "What's in that box? Why, it's a tiny replica of your office! And there's even a little you in there! And what's on the little desk... say - that's an even tinier box! And the little you is opening it, revealing an even tinier office! And in the tinier office there's- Hmm. You can think of a couple uses for this.", price = 1.55e50, icon = {20,31}, tier = 13, building = "Fractal engine", b1 = "Fractal engine", order = 1.300714e3 },
	{ name = "Hacker shades", desc = "Javascript consoles are twice as efficient.", quote = "I'm in.", price = 3.55e52, icon = {32,31}, tier = 13, building = "Javascript console", b1 = "Javascript console", order = 1.400715e3 },
	{ name = "Break the fifth wall", desc = "Idleverses are twice as efficient.", quote = "Huh, was that always there? Whatever it was, it's gone now. And what was behind is yours for the taking.", price = 6e54, icon = {33,31}, tier = 13, building = "Idleverse", b1 = "Idleverse", order = 1.500716e3 },
	{ name = "Cat ladies", desc = "Each kitten upgrade boosts grandma CpS by 29%.", quote = "Oh no. Oh no no no. Ohhh this isn't right at all.", price = 9000000000, icon = {32,3}, pool = "prestige", parents = {"Kitten angels"}, posX = 621, posY = -676, order = 2.74005e2 },
	{ name = "Milkhelp(R) lactose intolerance relief tablets", desc = "Each rank of milk boosts grandma CpS by 5%.", quote = "Aged like milk.", price = 900000000000, icon = {33,3}, pool = "prestige", parents = {"Cat ladies"}, posX = 618, posY = -537, order = 2.74006e2 },
	{ name = "Aura gloves", desc = "Cursor levels boost clicks by 5% each (up to cursor level 10).", quote = "Try not to high-five anyone wearing these. You don't want that mess on your hands.", price = 555555555, icon = {32,4}, pool = "prestige", parents = {"Halo gloves"}, posX = -225, posY = -520, order = 2.53003e2 },
	{ name = "Luminous gloves", desc = "Aura gloves are now effective up to cursor level 20.", quote = "These help power your clicks to absurd levels, but they're also quite handy when you want to light up the darkness on your way back from Glove World.", price = 55555555555, icon = {33,4}, pool = "prestige", parents = {"Aura gloves"}, posX = -150, posY = -631, order = 2.53004e2 },
	{ name = "Bokkenpootjes", desc = "Cookie production multiplier +5%.", quote = "Consist of 2 meringue halves joined by buttercream and dipped both ways in chocolate. Named after a goat's foot that probably stepped in something twice.", price = 3.162277660168e58, icon = {32,8}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e57, order = 1.0020721e4 },
	{ name = "Fat rascals", desc = "Cookie production multiplier +5%.", quote = "Almond-smiled Yorkshire cakes with a rich history and an even richer recipe. The more diet-conscious are invited to try the lean version, skinny scallywags.", price = 1e59, icon = {33,8}, pool = "cookie", power = 5, unlockCookies = 5e57, order = 1.0020722e4 },
	{ name = "Ischler cookies", desc = "Cookie production multiplier +5%.", quote = "Originating in the Austro-Hungarian Empire, these have spread throughout every country in eastern Europe and spawned just as many recipes, each claiming to be the original. The basis remains unchanged across all variants: two biscuits sandwiched around chocolate buttercream. Or was it jam?", price = 3.162277660168e59, icon = {32,9}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e58, order = 1.0020723e4 },
	{ name = "Matcha cookies", desc = "Cookie production multiplier +5%.", quote = "Green tea and cookies, a matcha made in heaven.", price = 3.162277660168e59, icon = {33,9}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e58, order = 1.0020724e4 },
	{ name = "Earl Grey macarons", desc = "Cookie production multiplier +3%.", quote = "Best served hot, make it so!", price = 1e28, icon = {32,10}, pool = "cookie", power = 3, unlockCookies = 5e26, unlockRequire = "Box of macarons", order = 1.0032725e4 },
	{ name = "Pokey", desc = "Cookie production multiplier +2%.", quote = "While commonly thought to be named so because it's fun to poke your classmates with these, Pokey-brand biscuit sticks actually get their name from their popularity in smoke-free prisons, where they're commonly smuggled and traded in lieu of cigarettes.", price = 5e36, icon = {33,10}, pool = "cookie", power = 2, unlockCookies = 2.5e35, unlockRequire = "Box of brand biscuits", order = 1.0030726e4 },
	{ name = "Cashew cookies", desc = "Cookie production multiplier +2%.", quote = "Let me tell you about cashews. Cashews are not nuts, but seeds that grow out of curious red or yellow fruits - which can be eaten on their own, or made into drinks. The shell around the nut itself contains a nasty substance that stains and irritates the hands of whoever handles it for too long. But that's okay, since now that you've read this you'll make sure it doesn't get in the cookies! Oh, you've already eaten how many? Okay then.", price = 99999999, icon = {32,7}, pool = "cookie", power = 2, unlockCookies = 4.99999995e6, order = 1.0000727e4 },
	{ name = "Milk chocolate cookies", desc = "Cookie production multiplier +2%.", quote = "A strange inversion of chocolate milk. For those who are a little bit too hardcore for white chocolate, but not hardcore enough for dark.", price = 499999995, icon = {33,7}, pool = "cookie", power = 2, unlockCookies = 2.499999975e7, order = 1.0001728e4 },
	{ name = "Brainy grandmas", desc = "Grandmas are twice as efficient. Cortex bakers gain +1% CpS per 17 grandmas.", quote = "A clever grandma to think up some cookies.", price = 9.5e25, icon = {10,9}, building = "Cortex baker", order = 2.55729e2 },
	{ name = "Principled neural shackles", desc = "Cortex bakers are twice as efficient.", quote = "A discriminatory, low-order neural net acting as a filter limiting what your cortex bakers can think and do. Really something you want to apply before they achieve full megasentience and realize they've got better things to do than materializing pastries for you, trust me.", price = 1.9e25, icon = {34,0}, tier = 1, building = "Cortex baker", b1 = "Cortex baker", order = 1.60073e3 },
	{ name = "Obey", desc = "Cortex bakers are twice as efficient.", quote = "Perfect mind control means perfect employee attendance and performance. Optimal mood stabilization is a nice side-effect.Happy happy everyone happy.Happy.", price = 9.5e25, icon = {34,1}, tier = 2, building = "Cortex baker", b1 = "Cortex baker", order = 1.600731e3 },
	{ name = "A sprinkle of irrationality", desc = "Cortex bakers are twice as efficient.", quote = "Your cortex bakers sometimes get bogged down by circular reasoning and stale ideas. A touch of chaos is just what they need to get back on track.", price = 9.5e26, icon = {34,2}, tier = 3, building = "Cortex baker", b1 = "Cortex baker", order = 1.600732e3 },
	{ name = "Front and back hemispheres", desc = "Cortex bakers are twice as efficient.", quote = "I mean, otherwise it's just unused space, yeah?", price = 9.5e28, icon = {34,13}, tier = 4, building = "Cortex baker", b1 = "Cortex baker", order = 1.600733e3 },
	{ name = "Neural networking", desc = "Cortex bakers are twice as efficient.", quote = "The effectiveness of your cortex bakers shoots up exponentially if you allow them to connect with each other. In practice this takes the form of many cosmic-sized nerds mumbling awkwardly about tech start-up ideas to each other.", price = 9.5e30, icon = {34,14}, tier = 5, building = "Cortex baker", b1 = "Cortex baker", order = 1.600734e3 },
	{ name = "Cosmic brainstorms", desc = "Cortex bakers are twice as efficient.", quote = "The wrinkled surfaces of your cortex bakers emit weather-scale ionic flares with every thought coursing through them. These pulses of pure intellectual energy are sent rippling through space, occasionally echoing back with even deeper philosophical complexity.", price = 9.5e32, icon = {34,15}, tier = 6, building = "Cortex baker", b1 = "Cortex baker", order = 1.600735e3 },
	{ name = "Megatherapy", desc = "Cortex bakers are twice as efficient.", quote = "A giant brain can feel unwell just like you and me sometimes, and it's the job of specialized engineers to locate and repair these bugs. We'll admit most of the budget in this was spent on constructing extremely large chaises longues for the brains to recline on.", price = 9.5e35, icon = {34,16}, tier = 7, building = "Cortex baker", b1 = "Cortex baker", order = 1.600736e3 },
	{ name = "Synaptic lubricant", desc = "Cortex bakers are twice as efficient.", quote = "A mind is only as fast as the axons that support it. Get those action potentials flowing smooth as silk with this 3 parts myelin/1 part canola oil spreadable paste. Also great on toast.", price = 9.5e38, icon = {34,17}, tier = 8, building = "Cortex baker", b1 = "Cortex baker", order = 1.600737e3 },
	{ name = "Psychokinesis", desc = "Cortex bakers are twice as efficient.", quote = "While your giant cortex bakers come equipped with ESP, they've only recently figured out how to manipulate the physical world with their thoughts - though for safety reasons, your legal team had them promise to only use these powers to scratch the itches in their cortical folds.", price = 9.5e41, icon = {34,18}, tier = 9, building = "Cortex baker", b1 = "Cortex baker", order = 1.600738e3 },
	{ name = "Spines", desc = "Cortex bakers are twice as efficient.", quote = "Your cortex bakers are now equipped with tentacular spine-like structures, which they can use like prehensile tails to pour themselves enormous cups of coffee or propel themselves around like very large, very smart, very slow tadpoles.", price = 9.5e44, icon = {34,19}, tier = 10, building = "Cortex baker", b1 = "Cortex baker", order = 1.600739e3 },
	{ name = "Neuraforming", desc = "Cortex bakers are twice as efficient.", quote = "By virtue of being planet-sized, your cortex bakers often boast their own atmospheres and seas of cerebrospinal fluid, and given enough time, their own ecosystems. This incredible new branch of life, evolved entirely out of neural material, can be put to good use as home-grown accountants and low-ranking technicians.", price = 9.5e48, icon = {34,28}, tier = 11, building = "Cortex baker", b1 = "Cortex baker", order = 1.60074e3 },
	{ name = "Epistemological trickery", desc = "Cortex bakers are twice as efficient.", quote = "Redefining what is -or isn't- a cookie through the power of philosophical discourse may result in some strange and wonderful things for your profit margins.", price = 9.5e52, icon = {34,30}, tier = 12, building = "Cortex baker", b1 = "Cortex baker", order = 1.600741e3 },
	{ name = "Every possible idea", desc = "Cortex bakers are twice as efficient.", quote = "Congratulations, your cortex bakers have exerted enough intellectual computation to permute through every single idea that can or ever will be conceived of. Any thought beyond this point is merely rediscovering a notion you've already archived. Hardly cause for cerebration.", price = 9.5e56, icon = {34,31}, tier = 13, building = "Cortex baker", b1 = "Cortex baker", order = 1.600742e3 },
	{ name = "Kitchen cabinets", desc = "Grandmas are twice as efficient.", quote = "A grandma's kitchen cabinet is a befuddling place. Through lesser-studied aggregating instincts, grandmas will tend to gradually fill all nearby cabinets with various sorts of things, such as curious coconut snacks or dietetic powders. By contract, these are legally yours, which opens up exciting opportunities for your substance investigation department.", price = 5e38, icon = {1,34}, tier = 14, building = "Grandma", b1 = "Grandma", order = 2.00743e2 },
	{ name = "Cookie mulch", desc = "Farms are twice as efficient.", quote = "Grinding surplus cookies into paste that you then spread onto your fields enables a strange feedback loop in the quality of your cookie crops. Cookie feeding on cookie should be an abomination, but then why does it taste so good?", price = 5.5e39, icon = {2,34}, tier = 14, building = "Farm", b1 = "Farm", order = 3.00744e2 },
	{ name = "Delicious mineralogy", desc = "Mines are twice as efficient.", quote = "Stratum after stratum, you've extracted strange new minerals heretofore unknown to geology. Ushering a new era of materials research, your scientists have been able to identify every new element your mines have discovered, including whatever those things are in the upgrade tier names.", price = 6e40, icon = {3,34}, tier = 14, building = "Mine", b1 = "Mine", order = 4.00745e2 },
	{ name = "N-dimensional assembly lines", desc = "Factories are twice as efficient.", quote = "Lines are depressingly 1-dimensional. Beyond assembly lines, we posit the existence of higher-order assembly entities, such as assembly squares, assembly cubes - perhaps even assembly tesseracts. Any deeper than that and we doubt we'll be able to write manuals your workers can read.", price = 6.5e41, icon = {4,34}, tier = 14, building = "Factory", b1 = "Factory", order = 5.00746e2 },
	{ name = "Cookie Points", desc = "Banks are twice as efficient.", quote = "A loyalty program wherein each purchase of your cookies comes with free Cookie Points, which can in turn be redeemed for more cookies, thus creating the self-sustaining economy you've been looking for.", price = 7e42, icon = {15,34}, tier = 14, building = "Bank", b1 = "Bank", order = 5.25747e2 },
	{ name = "Negatheism", desc = "Temples are twice as efficient.", quote = "Polytheism is a belief in multiple deities; monotheism in just one. Atheism is a belief in no deity whatsoever. Through logical succession it follows that this remains true when going into negative numbers, with belief systems involving minus 1 or more deities displaying unprecedented theological properties.", price = 1e44, icon = {16,34}, tier = 14, building = "Temple", b1 = "Temple", order = 5.50748e2 },
	{ name = "Magical realism", desc = "Wizard towers are twice as efficient.", quote = "More a social than thaumaturgical progress, magical realism refers to the normalization of modern technology among magic-users. It's totally fine for a wizard to drive a car! There's no stigma in waiting in line for coffee! Sure, take a phone call, send an email, whatever!", price = 1.65e45, icon = {17,34}, tier = 14, building = "Wizard tower", b1 = "Wizard tower", order = 5.75749e2 },
	{ name = "Cosmic foreground radiation", desc = "Shipments are twice as efficient.", quote = "Ah, this is a problem.", price = 2.55e46, icon = {5,34}, tier = 14, building = "Shipment", b1 = "Shipment", order = 6.0075e2 },
	{ name = "Arcanized glassware", desc = "Alchemy labs are twice as efficient.", quote = "You think your lab equipment enjoys taking part in these experiments violating all sorts of modern scientific precepts? Of course not. Thankfully, you've finalized the design of specialized beakers and flasks, recycled from the same glass used by the ancients to perform primeval alchemy, and therefore much less picky about the nature of the physical world.", price = 3.75e47, icon = {6,34}, tier = 14, building = "Alchemy lab", b1 = "Alchemy lab", order = 7.00751e2 },
	{ name = "Portal guns", desc = "Portals are twice as efficient.", quote = "At long last! The only weapon capable of killing a portal.", price = 5e48, icon = {7,34}, tier = 14, building = "Portal", b1 = "Portal", order = 8.00752e2 },
	{ name = "Timeproof upholstery", desc = "Time machines are twice as efficient.", quote = "Sometimes your time agents overshoot and end up having to fast-forward through the universe's entire history until they loop back to present time. It still takes a while, so they might as well travel in comfort and enjoy the show while they do.", price = 7e49, icon = {8,34}, tier = 14, building = "Time machine", b1 = "Time machine", order = 9.00753e2 },
	{ name = "Employee minification", desc = "Antimatter condensers are twice as efficient.", quote = "Using molecular shrinking technology, you've rendered your staff and their offices absolutely itty-bitty. The storage and productivity benefits are questionable but it's very fun listening to their tiny little complaints. They all signed the waivers, so maybe their new size will finally teach them to read the small print...", price = 8.5e50, icon = {13,34}, tier = 14, building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.000754e3 },
	{ name = "Hyperblack paint", desc = "Prisms are twice as efficient.", quote = "As the technology behind your prisms evolves, their storage becomes more and more problematic: within seconds, a single prism's reflective ability can set a whole underground hangar ablaze as it catches the slightest glint of light. However, once coated with this new shade of paint, its damage may be reduced to only giving third-degree burns to employees that stand too close.", price = 1.05e52, icon = {14,34}, tier = 14, building = "Prism", b1 = "Prism", order = 1.100755e3 },
	{ name = "Silver lining maximization", desc = "Chancemakers are twice as efficient.", quote = "Sometimes luck is a matter of perspective. Broke your ankle? What do you know, that cute nurse fixing you up might just be your future spouse. Lost your job? You were meant for greater things anyway! Developed a cookie allergy? There's no upshot to that, you sick monster.", price = 1.3e53, icon = {19,34}, tier = 14, building = "Chancemaker", b1 = "Chancemaker", order = 1.200756e3 },
	{ name = "Multiscale profiling", desc = "Fractal engines are twice as efficient.", quote = "Did you know that eating a cookie means the intestinal flora inside you is eating it too? Trillions of tiny bacterial mouths to feed, each with their own preferences. Surely this is room for flavor optimization. And then, of course, there's also the much bigger things that, in turn, eat you.", price = 1.55e54, icon = {20,34}, tier = 14, building = "Fractal engine", b1 = "Fractal engine", order = 1.300757e3 },
	{ name = "PHP containment vats", desc = "Javascript consoles are twice as efficient.", quote = "In essence, these are large server chambers meant to trap rogue PHP code, allowing it to execute far away from your javascript where it can do minimal harm.", price = 3.55e56, icon = {32,34}, tier = 14, building = "Javascript console", b1 = "Javascript console", order = 1.400758e3 },
	{ name = "Opposite universe", desc = "Idleverses are twice as efficient.", quote = "You've located a universe where everything is reversed: up is down, light is darkness, clowns are vegetarians - but worst of all, some lunatic there is manufacturing abominable amounts of anti-cookies. If these came into contact with yours, everything would be lost! Thanks to this discovery, you've been able to place the offending universe in permanent quarantine, and pray that there aren't more like it hiding around somewhere.", price = 6e58, icon = {33,34}, tier = 14, building = "Idleverse", b1 = "Idleverse", order = 1.500759e3 },
	{ name = "The land of dreams", desc = "Cortex bakers are twice as efficient.", quote = "Your planet brains have gained the ability to sleep, acting as a soft reboot which helps keep their pangenocidal impulses in check. It also allows them to commune in a shared dreamworld in which they can imagine what it's like to not exist as a disembodied cosmic horror forever fated to use its infinite intellect to devise new means of creating biscuits. You know, within reason.", price = 9.5e60, icon = {34,34}, tier = 14, building = "Cortex baker", b1 = "Cortex baker", order = 1.60076e3 },
	{ name = "Thoughts & prayers", desc = "Temples gain +5% CpS per cortex baker.Cortex bakers gain +0.1% CpS per temple.", quote = "The notion of sacredness arises in most sentient evolved brains and may benefit the development of cognition via abstract thought. This mechanism, however, is absent in designed minds such as your cortex bakers; this process attempts to add it back. Just make sure to keep them in check - you really don't want these things to develop organized religion.", price = 3.8e29, icon = {34,20}, tier = "synergy1", b1 = "Temple", b2 = "Cortex baker", order = 5.000761e3 },
	{ name = "Fertile minds", desc = "Farms gain +5% CpS per cortex baker.Cortex bakers gain +0.1% CpS per farm.", quote = "An acute intellect, artificial or not, requires plenty of vitamins. You fortuitously happen to be in charge of vast farming operations, only a few trillion acres of which need be requisitioned to grow the quantities of broccoli and kale to keep your planet-sized brains in tip-top shape. Open wide, here comes the airplane!", price = 3.8e35, icon = {34,29}, tier = "synergy2", b1 = "Farm", b2 = "Cortex baker", order = 5.000762e3 },
	{ name = "Fortune #019", desc = "Cortex bakers are 7% more efficient and 7% cheaper.", quote = "The smartest way to think is not to think at all.", price = 1.477777777778e53, icon = {34,32}, tier = "fortune", building = "Cortex baker", b1 = "Cortex baker", order = 1.9000763e4 },
	{ name = "Decillion fingers", desc = "Multiplies the gain from Thousand fingers by 20.", quote = "If you still can't quite put your finger on it, you must not be trying very hard.", price = 1e28, icon = {0,34}, tier = 14, order = 1.00764e2 },
