	{ name = "Unshackled idleverses", desc = "Tiered upgrades for Idleverses provide an extra +30% production.Only works with unshackled upgrade tiers.", quote = "Wait even faster.", price = 9.18330048e15, icon = {33,35}, pool = "prestige", parents = {"Unshackled javascript consoles"}, posX = 672, posY = 694, order = 7.68017e2 },
	{ name = "Unshackled cortex bakers", desc = "Tiered upgrades for Cortex bakers provide an extra +20% production.Only works with unshackled upgrade tiers.", quote = "Nothing is real. Everything is permitted.", price = 1.3408076085e16, icon = {34,35}, pool = "prestige", parents = {"Unshackled idleverses"}, posX = 561, posY = 663, order = 7.68018e2 },
	{ name = "Unshackled flavor", desc = "Unshackles all Plain-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "While the absence of flavoring may seem underwhelming, it allows innate aromas to be expressed at their most unadulterated.", price = 10000000, icon = {10,0}, pool = "prestige", parents = {"Label printer"}, posX = 544, posY = -143, order = 5.05001e2 },
	{ name = "Unshackled berrylium", desc = "Unshackles all Berrylium-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Berrylium is a synthetic gem with a simple shine to it. Sticky to the touch and susceptible to melting in high heat, it is frequently used in the food industry rather than as adornment, as its atomic structure imparts it a vaguely fruity flavor.", price = 1.810193359838e9, icon = {10,1}, pool = "prestige", parents = {"Unshackled flavor"}, posX = 654, posY = -188, order = 5.05002e2 },
	{ name = "Unshackled blueberrylium", desc = "Unshackles all Blueberrylium-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Blueberrylium is a refinement of berrylium, sharing nearly the same chemical makeup save for a few supplemental esters. These affect its flavor as well as its visual spectrum resonance.", price = 3.787995116153e10, icon = {10,2}, pool = "prestige", parents = {"Unshackled berrylium"}, posX = 773, posY = -199, order = 5.05003e2 },
	{ name = "Unshackled chalcedhoney", desc = "Unshackles all Chalcedhoney-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Raw chalcedhoney is found in complex nodules within the fossilized remains of ancient forests. Once purified, it becomes a semi-valuable stone with a pleasant, waxy smell.", price = 327680000000, icon = {10,13}, pool = "prestige", parents = {"Unshackled blueberrylium"}, posX = 890, posY = -175, order = 5.05004e2 },
	{ name = "Unshackled buttergold", desc = "Unshackles all Buttergold-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Buttergold was famously invented by the chef son of two molecular physicists. Neither closely related to butter nor to gold, yet similar in nutritional value, this glimmering substance can be frozen and preserve its hardness at room temperature, only regaining its malleability when heated up.", price = 1.746928107422e12, icon = {10,14}, pool = "prestige", parents = {"Unshackled chalcedhoney"}, posX = 995, posY = -116, order = 5.05005e2 },
	{ name = "Unshackled sugarmuck", desc = "Unshackles all Sugarmuck-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Sugarmuck refers to the gradual crust that seems to form spontaneously in the vicinity of candy-making equipment. Long ignored by confectioners, its harvesting process was discovered simultaneously in multiple countries during a global beet shortage.", price = 6.857003606358e12, icon = {10,15}, pool = "prestige", parents = {"Unshackled buttergold"}, posX = 1077, posY = -30, order = 5.05006e2 },
	{ name = "Unshackled jetmint", desc = "Unshackles all Jetmint-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "The striking taste of jetmint made it popular in the manufacture of various kinds of coffee-side treats until the awareness of its mild radioactivity became widespread. Today, its main uses are in cosmetics, owing to the refreshing sensation it produces on contact.", price = 2.178889971968e13, icon = {10,16}, pool = "prestige", parents = {"Unshackled sugarmuck"}, posX = 1131, posY = 77, order = 5.05007e2 },
	{ name = "Unshackled cherrysilver", desc = "Unshackles all Cherrysilver-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Cherrysilver is a patented alloy with peculiar aromatic properties; it is non-edible, but produces strong flavor responses while losing very little of its mass when licked, though this also leaves a harmless red tinge upon the tongue.", price = 5.931641601516e13, icon = {10,17}, pool = "prestige", parents = {"Unshackled jetmint"}, posX = 1150, posY = 195, order = 5.05008e2 },
	{ name = "Unshackled hazelrald", desc = "Unshackles all Hazelrald-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Hazelrald is a friable gemstone with complex green-brown inner reflections. It is considered ornamental in some cultures; in others, it may be consumed in small quantities as an upper-scale sweet.", price = 143489070000000, icon = {10,18}, pool = "prestige", parents = {"Unshackled cherrysilver"}, posX = 1134, posY = 313, order = 5.05009e2 },
	{ name = "Unshackled mooncandy", desc = "Unshackles all Mooncandy-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "While many get it mixed up with the trademarked snack of the same name made popular following its discovery, mooncandy is a very real mineral, first isolated within the space dust underneath astronaut boots. Left to its own devices in open air, a mooncandy crystal naturally spreads out and grows.", price = 3.162277660168e14, icon = {10,19}, pool = "prestige", parents = {"Unshackled hazelrald"}, posX = 1083, posY = 422, order = 5.0501e2 },
	{ name = "Unshackled astrofudge", desc = "Unshackles all Astrofudge-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "When you heat up the shimmering syrup oozing from mooncandy using a special caramelization process, you get astrofudge. Astrofudge is delicious and safe for humanoid consumption in certain quantities. Consult your local food safety agency for more details.", price = 6.463163443249e14, icon = {10,28}, pool = "prestige", parents = {"Unshackled mooncandy"}, posX = 1003, posY = 510, order = 5.05011e2 },
	{ name = "Unshackled alabascream", desc = "Unshackles all Alabascream-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Molecularly related to dairy, alabascream occurs naturally at high altitudes, forming in wispy filaments which were long indistinguishable from clouds. An expensive delight, it is also known as \"pilots' bane\".", price = 1.241250239661e15, icon = {10,30}, pool = "prestige", parents = {"Unshackled astrofudge"}, posX = 900, posY = 571, order = 5.05012e2 },
	{ name = "Unshackled iridyum", desc = "Unshackles all Iridyum-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Iridyum shares little in common with any other material known to mankind. Rather than simply smelled, it can be tasted from a distance, though remaining in its presence too long is ill-advised. Some high-end underground megacomputers may incorporate iridyum as part of their electronic components.", price = 2.262429955028e15, icon = {10,31}, pool = "prestige", parents = {"Unshackled alabascream"}, posX = 783, posY = 599, order = 5.05013e2 },
	{ name = "Unshackled glucosmium", desc = "Unshackles all Glucosmium-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Glucosmium is a glossy metal whose flavor matrix is bound to its current subjective chroma; in other words, its taste depends on which colors it's currently reflecting. Impractical to consume safely, its industrial applications range from transcontinental ballistics to paint varnish.", price = 3.944212159073e15, icon = {10,34}, pool = "prestige", parents = {"Unshackled iridyum"}, posX = 664, posY = 591, order = 5.05014e2 },
	{ name = "Delicate touch", desc = "The shimmering veil is more resistant, and has a 10% chance not to break. It also gives +5% more CpS.", quote = "It breaks so easily.", price = 149999999985, icon = {23,34}, pool = "prestige", parents = {"Reinforced membrane"}, posX = -310, posY = 945, order = 2.82008e2 },
	{ name = "Steadfast murmur", desc = "The shimmering veil is more resistant, and has a 10% chance not to break. It also gives +5% more CpS.", quote = "Lend an ear and listen.", price = 14999999999985, icon = {23,34}, pool = "prestige", parents = {"Delicate touch"}, posX = -466, posY = 911, order = 2.82009e2 },
	{ name = "Glittering edge", desc = "The shimmering veil is more resistant, and has a 10% chance not to break. It also gives +5% more CpS.", quote = "Just within reach, yet at what cost?", price = 1.5e15, icon = {23,34}, pool = "prestige", parents = {"Steadfast murmur"}, posX = -588, posY = 809, order = 2.8201e2 },
	{ name = "Distinguished wallpaper assortment", desc = "Contains more wallpapers for your background selector.", quote = "Do you ever think about the physicality of this place? Are you putting up these wallpapers in your office or something? Where are you, anyway?", price = 10000000, icon = {27,5}, pool = "prestige", parents = {"Basic wallpaper assortment"}, posX = 328, posY = 374, order = 3.28002e2 },
	{ name = "Sound test", desc = "Unlocks the jukebox, which allows you to play through every sound file in the game.", quote = "One two, one two. Is this thing on?", price = 99999999999, icon = {31,12}, pool = "prestige", parents = {"Fanciful dairy selection","Distinguished wallpaper assortment","Golden cookie alert sound"}, posX = 211, posY = 522, order = 3.28002e2 },
	{ name = "Jukebox", desc = "Play through the game's sound files!", price = 0, icon = {31,12}, pool = "toggle", order = 4.9900806e4 },
	{ name = "Dalgona cookies", desc = "Cookie production multiplier +5%.", quote = "A popular Korean candy-like treat. One of the twisted games people play with these is to carefully extract the shape in the middle, which may entitle one to another free dalgona. Skilled players may perform this over and over until bankrupting the snack vendor.", price = 1e60, icon = {26,34}, pool = "cookie", power = 5, unlockCookies = 5e58, order = 1.0020807e4 },
	{ name = "Spicy cookies", desc = "Cookie production multiplier +5%.", quote = "Containing chocolate chips prepared with hot peppers, just like the Aztecs used to make. These cookies are on the angry side.", price = 3.162277660168e60, icon = {27,34}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e59, order = 1.0020808e4 },
	{ name = "Smile cookies", desc = "Cookie production multiplier +5%.", quote = "As eyes are the windows to the soul, so too are these cookies' facial features a gaping opening unto their chocolatey innards. Is it happiness they feel? Or something less human?", price = 1e61, icon = {28,34}, pool = "cookie", power = 5, unlockCookies = 5e59, order = 1.0020809e4 },
	{ name = "Kolachy cookies", desc = "Cookie production multiplier +5%.", quote = "Adapted from a type of Central European pastry; neatly folded to hold a spoonful of delicious jam, as a bashful little gift for your mouth.", price = 3.162277660168e61, icon = {29,34}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e60, order = 1.002081e4 },
	{ name = "Gomma cookies", desc = "Cookie production multiplier +5%.", quote = "Surinamese cornflour cookies with sprinkles on top. The usage of corn imparts them a hint of chewy pizzazz - which you wouldn't get with wheat, a famously stuck-up grain.", price = 1e62, icon = {30,34}, pool = "cookie", power = 5, unlockCookies = 5e60, order = 1.0020811e4 },
	{ name = "Vegan cookies", desc = "Cookie production multiplier +5%.", quote = "A vegan riff on the classic chocolate chip cookie recipe with a couple substitutions: the butter is now coconut oil, the eggs are cornstarch, and the suckling pig was cleverly replaced with wheat gluten. You can hardly tell.", price = 3.162277660168e62, icon = {24,35}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e61, order = 1.0020812e4 },
	{ name = "Coyotas", desc = "Cookie production multiplier +5%.", quote = "A wide, delicious cookie from Mexico, usually filled with sticky brown sugar. Not to be confused with coyotas, the result of the crossbreeding between a North American canine and a Japanese car manufacturer.", price = 1e63, icon = {21,35}, pool = "cookie", power = 5, unlockCookies = 5e61, order = 1.0020813e4 },
	{ name = "Frosted sugar cookies", desc = "Cookie production multiplier +5%.", quote = "May be more style than substance, depending on the recipe. Nothing that hides itself under this much frosting should be trusted.", price = 3.162277660168e63, icon = {22,35}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e62, order = 1.0020814e4 },
	{ name = "Marshmallow sandwich cookies", desc = "Cookie production multiplier +5%.", quote = "S'mores' more civilized cousins: two regular chocolate chip cookies joined by a gooey, melty marshmallow. Theoretically one could assemble all kinds of other things this way. The mind races.", price = 1e64, icon = {31,34}, pool = "cookie", power = 5, unlockCookies = 5e62, order = 1.0020815e4 },
	{ name = "Web cookies", desc = "Cookie production multiplier +5%.", quote = "The original recipe; named for the delicate pattern inscribed on their surface by the baking process. Eating these can tell a lot about someone. Invented by well-connected bakers, no doubt.", price = 3.162277660168e64, icon = {25,35}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e63, order = 1.0020816e4 },
	{ name = "Steamed cookies", desc = "Cookie production multiplier +0%.", quote = "Localized entirely within this gaming platform? Yes! Baked with the power of steam, in a touch of cutting-edge modernity not seen since the industrial revolution.Only of any use in Cookie Clicker's Steam version, of course.", price = 3.162277660168e64, icon = {26,35}, pool = "debug", unlockCookies = 1.581138830084e63, order = 1.0020817e4 },
	{ name = "Deep-fried cookie dough", desc = "Cookie production multiplier +5%.", quote = "They'll fry anything these days. Drizzled in hot chocolate syrup, just like in state fairs. Spikes up your blood sugar AND your cholesterol!", price = 1e47, icon = {23,35}, pool = "cookie", power = 5, unlockCookies = 5e45, unlockRequire = "Box of maybe cookies", order = 1.0050818e4 },
	{ name = "Wrapping paper", desc = "You may now send and receive gifts with other players through buttons in the top-right of the Options menu.", quote = "Of course, you could've done this all along, but what kind of maniac sends presents without wrapping them first?", price = 999999, icon = {16,9}, pool = "prestige", parents = {"Heralds"}, posX = -418, posY = -126, order = 3.63002e2 },
	{ name = "Havreflarn", desc = "Cookie production multiplier +5%.", quote = "Thin, crispy, buttery; Norwegian for \"oat flakes\". The chocolate variant, dubbla chokladflarn, are a trip for the tongue as well, and we're not just talking about pronunciation.", price = 1e65, icon = {27,35}, pool = "cookie", power = 5, unlockCookies = 5e63, order = 1.002082e4 },
	{ name = "Alfajores", desc = "Cookie production multiplier +5%.", quote = "An alfajor is a treat made of two halves with many variations throughout the Spanish-speaking world, but commonly involving nuts, honey, and often dulce de leche. Despite popular misconception, alfajores act as pack leaders over betajores only in captivity.", price = 3.162277660168e65, icon = {28,35}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e64, order = 1.0020821e4 },
	{ name = "Gaufrettes", desc = "Cookie production multiplier +5%.", quote = "A gaufrette, you see, is French for a little gaufre, itself meaning waffle. A gaufrette, therefore, is a crispy, airy biscuit with the texture of a small waffle, related to the wafer, which may contain various fillings. It may also refer to a type of fried potato, but that's not what we're about here at Cookie Clicker.", price = 1e66, icon = {29,35}, pool = "cookie", power = 5, unlockCookies = 5e64, order = 1.0020822e4 },
	{ name = "Cookie bars", desc = "Cookie production multiplier +5%.", quote = "Baked as a large sheet of uniform cookie dough then cut into little squares, these are what chocolate brownies aspire to be in their most self-indulgent dreams. Not to be confused with a bar where cookies are served alongside alcoholic drinks, because that's not what we're about here at Cookie Clicker.", price = 3.162277660168e66, icon = {30,35}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e65, order = 1.0020823e4 },
	{ name = "Nines", desc = "Cookie production multiplier +2%.", quote = "Fancy little squares of dark chocolate filled with frosty mint fondant. Named after the suggested hour of consumption. Some would gatekeep them from the status of cookies as they involve very little in the way of pastry, but here at Cookie Clicker, that's just not what we're about.", price = 5e39, icon = {31,35}, pool = "cookie", power = 2, unlockCookies = 2.5e38, unlockRequire = "Box of brand biscuits", order = 1.0030824e4 },
	{ name = "Clone grandmas", desc = "Grandmas are twice as efficient. You gain +1% CpS per 18 grandmas.", quote = "Yet another grandma to replicate even more cookies.", price = 2.7e28, icon = {10,9}, building = "You", order = 2.55825e2 },
	{ name = "Cloning vats", desc = "You are twice as efficient.", quote = "You can finally replicate yourself through modern medical science, instead of manually like you've been doing.", price = 5.4e27, icon = {35,0}, tier = 1, building = "You", b1 = "You", order = 1.700826e3 },
	{ name = "Energized nutrients", desc = "You are twice as efficient.", quote = "Your clones are normally cultivated in saline solution and fed what could most adequately be described as \"fish flakes\". New developments in lactotrophic technology replace this with a bath of 3 parts milk and 1 part rice vinegar, absorbed dermally, which also helps your clones pop out with positively glowing skin.", price = 2.7e28, icon = {35,1}, tier = 2, building = "You", b1 = "You", order = 1.700827e3 },
	{ name = "Stunt doubles", desc = "You are twice as efficient.", quote = "More than simple multipliers of efficiency, you've taken to employing your clones as substitutes for any tasks that may prove harmful to you - such as visiting your more hazardous facilities, or enduring dinner with annoying business partners.", price = 2.7e29, icon = {35,2}, tier = 3, building = "You", b1 = "You", order = 1.700828e3 },
	{ name = "Clone recycling plant", desc = "You are twice as efficient.", quote = "Really just a fanciful name for a re-orientation center, where jobless clones may be assigned new tasks based on temperament and abilities. Categorically not a place where expired or unfit clones are processed into a nutritious beige paste, currently.", price = 2.7e31, icon = {35,13}, tier = 4, building = "You", b1 = "You", order = 1.700829e3 },
	{ name = "Free-range clones", desc = "You are twice as efficient.", quote = "Turns out your clones develop better focus, higher job performance and juicier meat if you let them roam around a little outside of assigned duties. Plus it gets the ethics committees off your back.", price = 2.7e33, icon = {35,14}, tier = 5, building = "You", b1 = "You", order = 1.70083e3 },
	{ name = "Genetic tailoring", desc = "You are twice as efficient.", quote = "No point in mindlessly replicating mother nature's mishaps when you've got full mastery over the human genome. Imbuing your clones with a slightly more flattering physique, a slightly improved metabolism, or slightly deadlier laser eyes is as easy as pushing some stem cells around. Just don't build them too superior to your own self, lest they get any ideas.", price = 2.7e35, icon = {35,15}, tier = 6, building = "You", b1 = "You", order = 1.700831e3 },
	{ name = "Power in diversity", desc = "You are twice as efficient.", quote = "On your routine inspections you've started noticing that some of your clones have... diverged. Subtly, each clone's personality has branched off from yours, their shifting minds pulling them into discrete clone-born cultures, microcosms of other paths you yourself could've taken had life treated you differently. This living tree of possibilities proves to be a boon for your self-knowledge and decision-making skills, and you don't even have to pester your alternate selves in other realities for it.", price = 2.7e38, icon = {35,16}, tier = 7, building = "You", b1 = "You", order = 1.700832e3 },
	{ name = "Self-betterment", desc = "You are twice as efficient.", quote = "World domination starts with oneself, and quality clones cannot be reliably produced if you, the original stock, are not in proper shape. Your specialists have devised a maintenance regimen that could extend your lifespan tenfold and even get rid of your morning grumpiness; you may have summarily fired every physician so far who's suggested that you work on your diet and perhaps cut down on the cookies, but frankly, you're warming up to the idea.", price = 2.7e41, icon = {35,17}, tier = 8, building = "You", b1 = "You", order = 1.700833e3 },
	{ name = "Source control", desc = "You are twice as efficient.", quote = "In the ongoing refinement of your genetic clones, the few gigabytes of your DNA have been passed around through e-mail attachments and USB keys a thousand times over and at this point your nucleosomes are practically common knowledge for anyone who works here. You're thinking people may be getting a little too casual about it - the other day, you walked past an office where one of your bioengineers was feeding treats to this horrid little hairless animal that you could swear had your face. High time to start tracing which data gets in whose hands and crack down on the silliness.", price = 2.7e44, icon = {35,18}, tier = 9, building = "You", b1 = "You", order = 1.700834e3 },
	{ name = "United workforce", desc = "You are twice as efficient.", quote = "What good is hiring so many of those random strangers to work in your factories when you've got all these perfectly loyal lab-grown copies of you lying around? They don't even take wages. It's not like they'd ever revolt and try to overthrow you or anything.", price = 2.7e47, icon = {35,19}, tier = 10, building = "You", b1 = "You", order = 1.700835e3 },
	{ name = "Safety patrols", desc = "You are twice as efficient.", quote = "Okay, so as it turns out mass-producing clones of a perhaps psychologically-complicated universe-spanning cookie magnate like yourself can result in a number of said clones developing what could be considered by some to be... say, antisocial behavior. No worries though, you've bred a new generation of extra-obedient copies, armed them to the teeth and given them full authority to deal with disorderly layabouts. It's fine. It's under control. It's fine.", price = 2.7e51, icon = {35,28}, tier = 11, building = "You", b1 = "You", order = 1.700836e3 },
	{ name = "Clone rights", desc = "You are twice as efficient.", quote = "Those vile little freaks in suits down in legal inform you that your clones, through some absurd technical oversight, still share enough genetic information with mankind to be considered human beings - which entitles them to food, shelter, basic dignity and all sorts of other nonsense. But the same loophole allows you to claim each of them as dependents and earn some wicked tax benefits, so really, that \"unalienable rights\" racket is quite alright.", price = 2.7e55, icon = {35,30}, tier = 12, building = "You", b1 = "You", order = 1.700837e3 },
	{ name = "One big family", desc = "You are twice as efficient.", quote = "The proportion of clones in your workforce having long eclipsed that of your other employees, you've become legally approved to qualify your galaxy-spanning corporation as a \"family business\" - a fact that you don't hesitate to blast twice hourly on every intercom in the company. Happily, your duplicates seem bolstered by these reminders, having come to regard you as this half-divine, half-parental entity, hallowed ancestor of all clones and all cookies. You're just hoping your folks at the labs can put the finishing touches on your immortality cure soon, or you shudder to think of the inheritance disputes to come.", price = 2.7e59, icon = {35,31}, tier = 13, building = "You", b1 = "You", order = 1.700838e3 },
	{ name = "Fine-tuned body plans", desc = "You are twice as efficient.", quote = "There is, after all, no reason to limit your genetic spawn to your original configuration. The clones maintaining your tunnels and vents can do with quite a few less limbs, while those working your labs don't mind the dexterity that comes with some extra. Your units down in flavor testing have taken on similar adaptations to fit their duties but you haven't quite worked up the guts to pay them a visit just yet.", price = 2.7e63, icon = {35,34}, tier = 14, building = "You", b1 = "You", order = 1.700839e3 },
	{ name = "Foam-tipped canes", desc = "Grandmas are twice as efficient.", quote = "Perhaps the result of prolonged service, your grandmas have developed all kinds of odd and aggressive hierarchies among themselves; these will help them not hurt each other as bad during their endless turf wars.", price = 5e42, icon = {1,36}, tier = 15, building = "Grandma", b1 = "Grandma", order = 2.0084e2 },
	{ name = "Self-driving tractors", desc = "Farms are twice as efficient.", quote = "Embarked AI lets your field vehicles sow and harvest cookie crops at any time of the day or night, and with so few human casualties, too!", price = 5.5e43, icon = {2,36}, tier = 15, building = "Farm", b1 = "Farm", order = 3.00841e2 },
	{ name = "Mineshaft supports", desc = "Mines are twice as efficient.", quote = "You were rather skeptical about installing such embarrassingly low-tech implements, but limiting the number of daily cave-ins really does help with that annoying employee turnover!", price = 6e44, icon = {3,36}, tier = 15, building = "Mine", b1 = "Mine", order = 4.00842e2 },
	{ name = "Universal automation", desc = "Factories are twice as efficient.", quote = "It's simple common sense; the more automation, the less work you have to do! Maybe one day you'll even automate yourself out of your own job. Exciting!", price = 6.5e45, icon = {4,36}, tier = 15, building = "Factory", b1 = "Factory", order = 5.00843e2 },
	{ name = "The big shortcake", desc = "Banks are twice as efficient.", quote = "You're not quite sure what this entails, but it must have been quite the cake for folks to lose their homes over it.", price = 7e46, icon = {15,36}, tier = 15, building = "Bank", b1 = "Bank", order = 5.25844e2 },
	{ name = "Temple traps", desc = "Temples are twice as efficient.", quote = "You've laid out your temples with (metaphorical) pitfalls, forcing adventurers to navigate through trappings (of power and wealth), ensuring that only the most pious (and poison dart-resistant) of them return with your precious cookies. These temples may be veritable mazes (of the soul) but perhaps you've lost yourself a little bit in the analogy too.", price = 1e48, icon = {16,36}, tier = 15, building = "Temple", b1 = "Temple", order = 5.50845e2 },
	{ name = "Polymorphism", desc = "Wizard towers are twice as efficient.", quote = "This astonishing new field of spellcasting can change any creature into another, its most widespread application being a wizard turning themselves into a different, smarter, stronger, more attractive wizard.", price = 1.65e49, icon = {17,36}, tier = 15, building = "Wizard tower", b1 = "Wizard tower", order = 5.75846e2 },
	{ name = "At your doorstep in 30 minutes or your money back", desc = "Shipments are twice as efficient.", quote = "Refund policies help rope in a ton of new clients and have practically no impact on your bottom line. You possess absolute mastery over time and space. You're never late. You couldn't be late if you tried.", price = 2.55e50, icon = {5,36}, tier = 15, building = "Shipment", b1 = "Shipment", order = 6.00847e2 },
	{ name = "The dose makes the poison", desc = "Alchemy labs are twice as efficient.", quote = "Iterative recipe refinement is a noble pursuit but maybe your cookies have come to contain, well, perhaps a bit too much cookie per cookie. Tweaking it down by a couple percents has helped reduce the amount of complaints to your toxicity call centers to almost nil!", price = 3.75e51, icon = {6,36}, tier = 15, building = "Alchemy lab", b1 = "Alchemy lab", order = 7.00848e2 },
	{ name = "A way home", desc = "Portals are twice as efficient.", quote = "You started this whole cookie venture on the simple kitchen counters of your own home. Your industrial and research facilities, sadly, have long since outgrown the confines of the little house, but you always knew it was still in there, buried somewhere. With a targeted portal, you could, conceivably, pay it a little visit for old times' sake...", price = 5e52, icon = {7,36}, tier = 15, building = "Portal", b1 = "Portal", order = 8.00849e2 },
	{ name = "Rectifying a mistake", desc = "Time machines are twice as efficient.", quote = "This whole time-travelling business has been a terrible mess and, frankly, far more trouble than was worth. It's decided: you'll hop in one of your time machines one last time, turn back the clock, knock on the door of your younger self and make a stern but convincing case against starting this entire nonsense in the first place. Oh hey, is someone at the door?", price = 7e53, icon = {8,36}, tier = 15, building = "Time machine", b1 = "Time machine", order = 9.0085e2 },
	{ name = "Candied atoms", desc = "Antimatter condensers are twice as efficient.", quote = "You know what, just eat the suckers, yeah?", price = 8.5e54, icon = {13,36}, tier = 15, building = "Antimatter condenser", b1 = "Antimatter condenser", order = 1.000851e3 },
	{ name = "Lab goggles but like cool shades", desc = "Prisms are twice as efficient.", quote = "Mandatory equipment in your prismatic labs, and dashingly stylish at that. A smidge safer than just squinting at the twinkly things.", price = 1.05e56, icon = {14,36}, tier = 15, building = "Prism", b1 = "Prism", order = 1.100852e3 },
	{ name = "Gambler's fallacy fallacy", desc = "Chancemakers are twice as efficient.", quote = "Yes, just because you've been on a losing streak doesn't mean the next one is bound to be the win you've been hoping for, but then again, it doesn't statistically have less of a chance either, does it now?", price = 1.3e57, icon = {19,36}, tier = 15, building = "Chancemaker", b1 = "Chancemaker", order = 1.200853e3 },
	{ name = "The more they stay the same", desc = "Fractal engines are twice as efficient.", quote = "Exhausted by your fractals department and its obsession with self-similarity, you've decided to take a break and seek things in life entirely disconnected from any other; alas! You find the task impossible, for all things in this world relate to all others - in each cookie, the structure of the universe; in each person, their fellow man. Cor blimey, you can't even look at broccoli in peace.", price = 1.55e58, icon = {20,36}, tier = 15, building = "Fractal engine", b1 = "Fractal engine", order = 1.300854e3 },
	{ name = "Simulation failsafes", desc = "Javascript consoles are twice as efficient.", quote = "Oh, for pete's sake, you bit into a cookie and it gave you a runtime error. You've been trapped in the old matrix gambit again! Time to shut everything down and prepare for extraction into what is hopefully the real layer of reality where learning kung-fu takes time and the biscuits don't throw memory overflow exceptions.", price = 3.55e60, icon = {32,36}, tier = 15, building = "Javascript console", b1 = "Javascript console", order = 1.400855e3 },
	{ name = "The other routes to Rome", desc = "Idleverses are twice as efficient.", quote = "Did you know every idleverse follows its own path of sequential buildings, sometimes quite dissimilar to our own? Grandpas, wind turbines, through the power of music, friendship, or legislation; those folks in there discovered ways to make cookies out of any random venue. Some of them don't even have idleverses, can you imagine?", price = 6e62, icon = {33,36}, tier = 15, building = "Idleverse", b1 = "Idleverse", order = 1.500856e3 },
	{ name = "Intellectual property theft", desc = "Cortex bakers are twice as efficient.", quote = "Okay, you'll admit you're maybe starting to run out of new baking recipes. But what if... you were to pilfer your cortex bakers for ideas and disguise them as your own cookies? Delightfully devilish!", price = 9.5e64, icon = {34,36}, tier = 15, building = "Cortex baker", b1 = "Cortex baker", order = 1.600857e3 },
	{ name = "Reading your clones bedtime stories", desc = "You are twice as efficient.", quote = "I don't know, they seem to like it.", price = 2.7e67, icon = {35,36}, tier = 15, building = "You", b1 = "You", order = 1.700858e3 },
	{ name = "Accelerated development", desc = "Time machines gain +5% CpS per You.You gain +0.1% CpS per time machine.", quote = "Your clones may grow a little faster than your vanilla human being, but it's still a little silly having to wait so many years for them to reach a usable age. A quick trip in your time machines takes care of that; it doesn't technically age them faster, they're just sent to another point in time for a while where they live out a formative youth.", price = 1.08e32, icon = {35,20}, tier = "synergy1", b1 = "Time machine", b2 = "You", order = 5.000859e3 },
	{ name = "Peer review", desc = "Javascript consoles gain +5% CpS per You.You gain +0.1% CpS per javascript console.", quote = "Code is only as good as the number of eyes on it, so imagine how flawlessly your systems could operate if you had endless copies of yourself triple-checking everything! Just make sure to teach them proper indenting etiquette.", price = 1.08000142e38, icon = {35,29}, tier = "synergy2", b1 = "Javascript console", b2 = "You", order = 5.00086e3 },
	{ name = "Fortune #020", desc = "You are 7% more efficient and 7% cheaper.", quote = "No matter how hard you try, you're never truly alone.", price = 4.2e55, icon = {35,32}, tier = "fortune", building = "You", b1 = "You", order = 1.9000861e4 },
	{ name = "Personal biscuit", desc = "Cookie production multiplier +10%.", quote = "Rewarded for owning 700 of everything.This biscuit was designed and bred through the combined fields of baking and exploratory genomics, resulting in a perfect biscuit-shaped organism, sole exemplar of its own species; infused with a sapient mind and bootstrapped with a copy of your own consciousness, it slumbers immortally within its display case, dreaming idly about much the same things you do.", price = 1e65, icon = {21,36}, pool = "cookie", power = 10, order = 1.0300862e4 },
	{ name = "Unshackled glimmeringue", desc = "Unshackles all Glimmeringue-tier upgrades, making them more powerful.Only applies to unshackled buildings.", quote = "Lightweight, digestible, and endlessly fragile, glimmeringue not only enjoys a privileged place in the \"spectacle cooking\" industry - it also shares most of its other properties with asbestos, save for thermal insulation.", price = 6.617355139184e15, icon = {10,36}, pool = "prestige", parents = {"Unshackled glucosmium"}, posX = 552, posY = 548, order = 5.05015e2 },
	{ name = "Unshackled You", desc = "Tiered upgrades for You provide an extra +10% production.Only works with unshackled upgrade tiers.", quote = "Guess who?", price = 1.92e16, icon = {35,35}, pool = "prestige", parents = {"Unshackled cortex bakers"}, posX = 461, posY = 608, order = 7.68019e2 },
	{ name = "Kitten strategists", desc = "You gain more CpS the more milk you have.", quote = "out with the old in with the mew, sir", price = 9e50, icon = {18,36}, tier = 15, kitten = true, order = 2.0000865e4 },
	{ name = "Baklavas", desc = "Cookie production multiplier +4%.", quote = "Layers of paper-thin dough and crushed pistachios, absolutely sticky with honey and all kinds of other good things; just what you need to conceal your identity during that bank heist.", price = 1e47, icon = {28,36}, pool = "cookie", power = 4, unlockCookies = 5e45, unlockRequire = "Box of pastries", order = 1.0040866e4 },
	{ name = "Snowball cookies", desc = "Cookie production multiplier +5%.", quote = "Melts in your mouth! Made with chopped nuts and heaps of icing sugar. Serve cold. Resist the urge to throw.", price = 1e67, icon = {22,36}, pool = "cookie", power = 5, unlockCookies = 5e65, order = 1.0020867e4 },
	{ name = "Sequilhos", desc = "Cookie production multiplier +5%.", quote = "Buttery cornstarch-based cookies eaten in Brazil; the decorative grooves are from pressing down on them with the back of a fork, though in a pinch you may also just slash them with Wolverine-style wrist blades.", price = 3.162277660168e67, icon = {23,36}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e66, order = 1.0020868e4 },
	{ name = "Hazelnut swirlies", desc = "Cookie production multiplier +5%.", quote = "The cocoa content of the paste inside is unfortunately just slightly too low for these to legally qualify as chocolate cookies. Also the name of a particularly nasty bullying move.", price = 1e68, icon = {24,36}, pool = "cookie", power = 5, unlockCookies = 5e66, order = 1.0020869e4 },
	{ name = "Spritz cookies", desc = "Cookie production multiplier +5%.", quote = "Squeezed through special cookie presses into all kinds of fun shapes. Enjoyed around the holidays in Germany, along other delicious treats such as boiled cabbage and potato salad.", price = 3.162277660168e68, icon = {25,36}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e67, order = 1.002087e4 },
	{ name = "Mbatata cookies", desc = "Cookie production multiplier +5%.", quote = "Squishy cookies from Malawi. The core ingredient is sweet potatoes; the raisins and heart shape are optional, if you hate fun.", price = 1e69, icon = {26,36}, pool = "cookie", power = 5, unlockCookies = 5e67, order = 1.0020871e4 },
	{ name = "Springerles", desc = "Cookie production multiplier +5%.", quote = "A springerle is an ancient anise-flavored biscuit from Central Europe, imprinted by a wooden mold with any kind of interesting design such as a commemorative scene, an intricate pattern or, ah, perhaps a little horsie.", price = 3.162277660168e69, icon = {27,36}, pool = "cookie", power = 5, unlockCookies = 1.581138830084e68, order = 1.0020872e4 },
	{ name = "Undecillion fingers", desc = "Multiplies the gain from Thousand fingers by 20.", quote = "Whatever you touchturns to dough in your clutch.", price = 1e31, icon = {0,36}, tier = 15, order = 1.00873e2 },
	{ name = "Omniplast mouse", desc = "Clicking gains +1% of your CpS.", quote = "This mouse is, by virtue of the strange elements that make it up, present in every position in space simultaneously, in a manner; this alleviates its owner from the need to move it around, redirecting all such kinetic power to the intensity of its clicks.", price = 5e32, icon = {11,36}, tier = 15, order = 1.50874e2 },
	{ name = "Wrinkler ambergris", desc = "Cookie production multiplier +6%.All upgrades are 1% cheaper.Cost scales with CpS.", quote = "Occasionally regurgitated by wrinklers.The byproduct of some obscure metabolic process or other, it is as rare and precious as it is pungent.Makes for a great toast spread.", price = 0, icon = {31,36}, lasting = true, order = 2.5050875e4 },
}
